programs.haiku:
"""Layer-0 MLP down_proj component 960: a weak, diffuse, word-level signal.

What it does: it is nearly silent almost everywhere (CI never passes), and where it
has a sign it is mostly set by the current word:
  - newsroom / broadcast role nouns (host, producer, reporter, correspondent,
    announcer, commercial, ...) push it clearly negative;
  - common prepositions (of, for, by, on, to, ...) push it slightly negative;
  - possessive determiners (his, her, my, ...) push it slightly positive;
  - copulas and 'have' (is, was, had, ...) push it slightly positive.
Everything else is predicted as 0. The values are rounded group means from
about 4k training rows; the rules explain only a few tenths of a percent of variance.
"""

READS = ()

MEDIA_ROLES = {
    "host", "producer", "reporter", "correspondent", "announcer", "commercial",
    "anchor", "editor", "journalist", "broadcast", "reporting", "npr",
}
PREPOSITIONS = {"of", "for", "by", "on", "to", "with", "from", "among", "about", "at", "in"}
POSSESSIVES = {"his", "her", "my", "our", "their", "your", "its"}
COPULAS = {"was", "is", "are", "be", "were", "been", "had", "has", "have"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in MEDIA_ROLES:
        value = -0.05
    elif word in PREPOSITIONS:
        value = -0.004
    elif word in POSSESSIVES:
        value = 0.012
    elif word in COPULAS:
        value = 0.003
    else:
        value = 0.0
    return carry, value

programs.sol:
"""Detect unspaced e-initial word fragments after consonant-heavy pieces.

The response depends on the preceding consonant and decreases as either
fragment gets longer. A preceding fragment containing vowels weakens it.
Accented Latin e, Cyrillic е, and Greek ε receive small corrections, as do
some following letters. Coefficients are fitted on training text.
"""
import unicodedata

READS = ()
VOWELS = frozenset("aeiouyаеёиоуыэюяαεηιουω")
STRONG = frozenset("bfgбгф")
MEDIUM = frozenset("cpvjwzчщшжпвцз")
OTHER = frozenset("dtknrslmдтнрслмк")


def plain(s):
    return "".join(c for c in unicodedata.normalize("NFD", s.lower())
                   if not unicodedata.combining(c))


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    s = plain(token)
    if s[:1] not in ("e", "е", "ε"):
        return None, -0.002
    previous = ""
    if len(prefix.token_ids) > 1:
        if prefix.document_ids[-2] == prefix.document_ids[-1]:
            previous = prefix.token_strings[-2]
    p = plain(previous)
    last = p[-1:]
    letters = "".join(c for c in p if c.isalpha())
    consonant = bool(last) and last.isalpha() and last not in VOWELS
    cluster = consonant and not any(c in VOWELS for c in letters)
    value = -0.04
    if consonant:
        if last == "h":
            gain = 2.03
        elif last in STRONG:
            gain = 1.51
        elif last in MEDIUM:
            gain = 1.07
        elif last in OTHER:
            gain = 0.84
        else:
            gain = 0.55
        gain *= max(0.05, 1 - 0.133 * (min(len(letters), 8) - 1))
        gain *= max(0.05, 1 - 0.177 * max(0, min(len(s), 9) - 2))
        value += gain * (1.0 if cluster else 0.54)
        if s[1:2] in ("p", "п", "y") and cluster:
            value += 0.46
        elif s[1:2] in ("c", "h"):
            value += 0.135
        elif s[1:2] == "s":
            value += 0.08
        elif s[1:2] in ("r", "d", "ж", "ч"):
            value -= 0.095
    elif last in ("e", "е"):
        value -= 0.15
    value += 0.07 * token.isupper() - 0.165 * (s != token.lower())
    value += -0.08 if s[0] == "е" else 0.21 if s[0] == "ε" else 0.0
    if not previous:
        value += 0.11
    return None, float(value)

programs.luna:
"""Predict negative pulses for conspicuous encoding and formatting marks: a
space-prefixed replacement glyph, nonbreaking spaces, math-context
backslashes, Arabic combining marks, and the emoji variation selector."""

import unicodedata

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "\ufffd" in token and token.startswith(" "):
        return None, -0.59
    if "\u00a0" in token:
        return None, -0.35

    if "\\" in token:
        recent = "".join(prefix.token_strings[-9:-1])
        if "$" in recent:
            return None, -0.39
        if any(mark in recent for mark in ("math", "frac", "left", "right", "sum")):
            return None, -0.25

    if any("ARABIC" in unicodedata.name(c, "") and
           unicodedata.category(c) == "Mn" for c in token):
        return None, -0.35
    if "\ufe0f" in token:
        return None, -0.4
    return None, 0.0

programs.sol:
"""Approximate an assignment-versus-equation separator signal.

At '=', identifier length, member access, indentation and declarations suggest
code assignments: these receive negative values. Numerals, superscripts and
some mathematical expression endings receive positive values. Short variable
names are weaker unless code syntax disambiguates them. LaTeX commands are
not treated as code names. Quoted-key colons, updates and comparisons have
smaller negative values; other tokens receive zero.

Only a 160-character line suffix is retained. Literal and escaped newlines
reset it; a new document resets all state. This is a syntax-based estimate,
not an exact account of spelling-specific and longer-context variation.
"""
import re

READS = ()
IDENTIFIER = re.compile(r'[A-Za-z_$][A-Za-z0-9_$]*$')
DECLARATION = re.compile(
    r'^\s*[\d+-]*\s*(?:export\s+)?'
    r'(?:const|let|var|val|type|typealias)\b'
    r'|\b(?:int|double|float|bool|char|string)(?:\s+const)?\s'
)
ARITHMETIC = re.compile(
    r'[A-Za-z0-9)]\s*[+−-]\s*\d*[A-Za-z][A-Za-z0-9_]*$'
)
LATEX = re.compile(r'\\[A-Za-z]+|\$\$')


def equality(left, spaced):
    left = left.rstrip()
    scale = 1.0 if spaced else 0.55
    indented = left.lstrip('+-').startswith(('  ', '\t'))
    code = (indented or bool(DECLARATION.search(left)))
    code = code and not LATEX.search(left)
    word = IDENTIFIER.search(left)
    if word:
        name = word.group()
        before = left[:word.start()]
        if '$' in name:
            name = name.rsplit('$', 1)[-1]
        if not name:
            return 0.0
        if before.endswith('\\'):
            return 0.0
        if before.endswith('.'):
            return scale * -2.9
        short_operand = len(name) <= 2 or (len(name) <= 4 and name[-1].isdigit())
        if not code and short_operand:
            if ARITHMETIC.search(left[-45:]):
                return 0.9
        if not code and LATEX.search(left) and len(name) <= 4:
            return 0.0
        if any(c.isdigit() for c in name):
            value = -2.4 if code and len(name) > 5 else -1.5
            return scale * value
        if code:
            return scale * (-2.5 if len(name) <= 2 else -3.0)
        if len(name) <= 2:
            return scale * (-0.7 if left == name else -0.1)
        return scale * (-1.4 if len(name) <= 5 else -2.2)
    if left.endswith('>') and code:
        return scale * -2.5
    if left.endswith(']'):
        return scale * (-1.9 if code else -0.6)
    if left.endswith(')'):
        return scale * -1.3 if code else 0.85
    if left.endswith('}'):
        return scale * -1.2 if code else 0.4
    if left.endswith(tuple('0123456789²³')):
        if re.search(r'\b(?:ON|WHERE)\s+\d+$', left):
            return -1.9
        return 0.9
    if not left:
        return -1.8 if spaced else 0.1
    if left.endswith('='):
        return 0.0
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    line = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    op = token.strip()
    value = 0.0
    if op == '=':
        value = equality(line, token.startswith(' '))
    elif op.startswith('=') and not op.startswith(('==', '=>')):
        if op.startswith('=-'):
            value = 0.75
        elif op.startswith('=('):
            value = 0.4
        elif op == '=\\':
            value = 0.35
        elif op.startswith(('=\"', "='", '=\\')):
            value = -0.1
        else:
            value = 0.4 * equality(line, False)
    elif op.startswith((')=', '}=')):
        value = 0.55
    elif op == ':=':
        value = -1.5 if token.startswith(' ') else 0.0
    elif op in ('+=', '-=', '*=', '/='):
        value = -1.0 if token.startswith(' ') else 0.0
    elif op == '=>':
        value = -0.4
    elif op in ('!=', '!=='):
        value = -0.4
    elif op in ('==', '==='):
        value = -0.1 if token.startswith(' ') else 0.1
    elif op in ('\":', "':"):
        value = -0.5
    elif op == '?:':
        value = -1.0
    elif token in (':', ' :'):
        word = IDENTIFIER.search(line.rstrip())
        indented = line.startswith(('  ', '\t'))
        if word:
            upper = word.group()[0].isupper()
            if indented:
                value = -0.3 if upper else -0.48
            else:
                value = -0.07 if upper else -0.15
        elif token.startswith(' '):
            value = -0.25
    line = (line + token).replace('\\t', '\t').replace('\\n', '\n')
    line = line.split('\n')[-1][-160:]
    return (doc, line), float(value)

programs.luna:
"""Estimate equality-mark activations from nearby arithmetic or code syntax.
The short character history resets at document boundaries; unrelated tokens get 0.
"""
READS = ()
ASSIGNMENT = {":=", "+=", "-=", "*=", "/=", "=>", "==", "!=", "<=", ">="}
MATH = set("+-*/^×÷√")
CODE_WORDS = ("return", "function", "class ", "const ", "let ", "var ", "def ",
              "import ", "self.", "onclick", "->", "$", "println")


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    before = "" if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    op = token.strip()
    value = 0.0

    if "=" in op:
        tail = before[-64:]
        if op in ASSIGNMENT:
            value = -0.35
        elif (any(c.isdigit() for c in tail)
              and any(c in MATH for c in tail)
              and not any(w in tail for w in CODE_WORDS)
              and not any(c in tail for c in "{};'\"`")):
            value = 0.55
        elif any(w in tail for w in CODE_WORDS) or any(c in tail for c in ".{};'\"`$"):
            value = -0.35
        else:
            value = -0.12
    elif op == ":" and any(c.isalpha() for c in before[-24:]):
        value = -0.08

    return (doc, (before + token)[-128:]), float(2.0 * value)

programs.sol:
"""A lexical detector for gaps in time, space and value.

Delay/offset cues dominate; intervals, deltas, margins and nulls are weaker.
Recognize common English forms, code names and Chinese/Japanese gap words.
'Between' is weaker in comparisons and negative in relationship phrases.
A few suffixes and 'of' retain the preceding gap cue. Reasoning markers and
workspace paths have independent responses, as do presence/value and
programming words. This does not infer real gaps or general absence.
"""

READS: tuple[str, ...] = ()

# Concept families; activation strengths are rounded training averages.
TIME_GAPS = {
    'delay': 2.8, 'timedelta': 2.8, 'delays': 2.5, 'delayed': 2.2,
    'delaying': 2.2, 'interval': 1.65, 'intervals': 1.8, 'latency': 1.6,
    'period': 0.8, 'periods': 0.7, 'schedule': 0.7, 'schedules': 0.7,
    'timeout': 0.7, 'elapsed': 1.0, 'duration': 0.5,
    'timestamp': 1.0, 'timestamps': 1.0, 'timespan': 2.0,
    'datetimeoffset': 2.2, 'deltatime': 1.8,
}
SPATIAL_GAPS = {
    'offset': 3.1, 'offsets': 2.8, 'margin': 1.8, 'margins': 1.0,
    'spacing': 1.9, 'spaced': 2.1, 'padding': 1.8, 'padded': 0.7,
    'gap': 1.15, 'gaps': 1.15, 'separation': 1.05,
    'distance': 0.7, 'distances': 0.6, 'apart': 0.5, 'within': 0.4,
    'shift': 0.6, 'shifts': 0.6, 'shifted': 0.7, 'shifting': 0.6,
    'overlap': 0.8, 'overlaps': 0.7, 'overlapping': 0.7, 'overlay': 0.7,
    'separated': 0.65, 'separator': 0.6, 'pad': 0.5, 'span': 0.45,
    'cushion': 1.1, 'barrier': 0.8, 'barriers': 0.9, 'delimiter': 1.3,
}
VALUE_GAPS = {
    'difference': 1.05, 'differences': 0.9, 'diff': 0.5, 'differ': 0.55,
    'null': 1.15, 'nil': 0.5, 'nullptr': 0.85, 'nullable': 0.55,
    'threshold': 1.05, 'thresholds': 0.9, 'tolerance': 1.1,
    'deviation': 0.6, 'epsilon': 0.45,
}
# Translations/fragments: interval, delay, padding, separation and difference.
EAST_ASIAN_GAPS = {
    '隔': 2.9, '间隔': 3.8, '延迟': 2.2, '迟': 2.3, '遲': 1.55,
    '差距': 2.3, '垫': 2.0, '隔离': 1.8, '隙': 1.4, '距': 1.8,
    '差': 0.85, '差异': 0.9, '差别': 0.8, '区别': 0.9, '違い': 1.2,
    '移': 1.1, '距离': 1.25, '延': 0.95, '偏': 0.9, '晚': 0.95,
    '提前': 0.8, '間': 0.4, '之间': 0.5, '之间的': 0.5,
}
GAP_CUES = TIME_GAPS | SPATIAL_GAPS | VALUE_GAPS | EAST_ASIAN_GAPS
FRAGMENTS = {
    'del': 0.58, 'elta': 1.0, 'elay': 1.0, 'edelta': 2.1,
    'ffset': 2.3, 'erval': 1.1, 'ervals': 1.4, 'psilon': 0.67,
}
RELATIONS = set('relationship relationships relation relations association '
                'correlation correlations correspondence link'.split())
COMPARISONS = set('difference differences distinction distinguish comparison '
                  'differentiate similarity angle ratio balance'.split())


def normalize(token):
    return token.strip().strip('._/\\():,;=-[]<> ')


MARKERS = {
    '<think>': 0.49, '</think>': 0.63,
    '<tool_response>': -0.16, '</tool_response>': -0.12,
    '/workspace': 0.7, '@@': 0.55,
}


def lexical_score(token):
    if token in MARKERS:
        return MARKERS[token]
    original = normalize(token)
    word = original.lower()
    if word == 'delta':
        return 0.8 if original[:1].isupper() else 1.6
    if original in {'δ', 'Δ', 'ε'}:
        return {'δ': 1.4, 'Δ': 0.85, 'ε': 0.15}[original]
    if word == 'between':
        return 0.5
    if word in {'presence', 'coverage', 'awareness', 'worth'}:
        return 0.67
    if word in {'program', 'programs', 'programming', '应用程序'}:
        return -0.4
    if word == 'del' and original == 'DEL':
        return 1.4
    return GAP_CUES.get(word, FRAGMENTS.get(word, -0.002))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    word = normalize(token).lower()
    previous, strength = ('', 0.0)
    if carry is not None and carry[0] == doc:
        previous, strength = carry[1:]
    base = lexical_score(token)
    value = base
    if word == 'between':
        if previous in RELATIONS:
            value = -0.16
        elif previous in COMPARISONS:
            value = 0.23
        elif previous in {'time', 'interval', 'intervals', 'gap', 'period', 'delay'}:
            value = 0.87
        elif previous in {'is', 'be', 'are', 'in', 'located', 'space', 'path'}:
            value = 0.68
        elif previous == 'distance':
            value = 0.54
    elif word in {'interval', 'intervals'}:
        if previous in {'time', 'short', 'regular', 'set'}:
            value += 0.6
        elif previous in {'confidence', 'prediction', 'predictive'}:
            value -= 0.45
    elif word == 'of' and strength > 0.2:
        value += 0.27 * strength
    elif token in {'ing', 'ed', 's'} and strength > 0.2:
        value += {'ing': 0.8, 'ed': 0.4, 's': 0.5}[token] * strength
    elif word == 'language' and previous == 'programming':
        value = -0.8
    return (doc, word, base), float(value)

programs.luna:
"""Estimate a sparse feature for gaps, differences, and relative position.

It gives the largest estimates to words naming a difference or delay,
moderate estimates to spatial relations, and a smaller estimate to presence
or absence words. It uses only the current token.
"""
READS = ()

DIFFERENCES = {"difference", "gap", "delta", "discrepancy", "offset"}
SPATIAL_RELATIONS = {
    "between", "distance", "apart", "overlap", "overlapping", "span",
    "interval", "overhead", "backdrop", "airspace", "space", "shifts",
}
EMPTY_OR_PRESENT = {"null", "nil", "presence", "absence", "empty", "void"}
TIMING = {"delay", "lag", "remaining", "leftover"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word == "delay":
        value = 2.9
    elif word in DIFFERENCES or word in {"null", "nil"}:
        value = 1.2
    elif word in SPATIAL_RELATIONS:
        value = 0.65
    elif word in EMPTY_OR_PRESENT or word in TIMING:
        value = 0.55
    elif word in {"残", "疏", "間"}:
        value = 0.6
    else:
        value = 0.0
    return None, value

programs.sol:
"""A lexical response to essays and reflective writing, plus a spacing response.

The strongest word is 作文 (Chinese for an essay/composition). Related forms
and reflection words are weaker. Tab-followed spaces give positive pulses;
plain spacing is stronger after content than immediately after a newline.
These are approximate token-level responses, not a detector of whole essays.
"""

READS = ()

# Words for written forms, expression, and reflection. Values are fitted approximations.
WRITING_AND_REFLECTION = {
    '作文': 2.45,  # essay/composition
    '日记': 0.88,  # diary
    '散文': 0.76,  # prose
    '心得': 0.57,  # reflections
    '写作': 0.45,  # writing
    '感悟': 0.45,  # reflective insight
    '论文': 0.31,  # paper/thesis
    '感': 0.31,    # feeling
    '感动': 0.31,  # moved emotionally
    '文章': 0.22,  # article
    '记': 0.22,    # record
    '稿': 0.22,    # draft
    '演讲': 0.22,  # speech
    '感受': 0.22,  # impressions
    'diary': 0.22,
    'documentary': 0.22,
    'memoir': 0.22,
    'sermon': 0.40,
}
BLOG_WORDS = {'blog', 'blogs', 'blogger', 'bloggers', 'blogging'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    after_newline = (
        prefix.position > 0
        and prefix.document_ids[-1] == prefix.document_ids[-2]
        and prefix.token_strings[-2].endswith('\n')
    )
    value = WRITING_AND_REFLECTION.get(word, 0.0)
    if word.endswith('篇') and len(word) <= 3:  # unit of written text
        value = 0.57
    elif word == 'essay':
        value = 0.98 + 0.25 * token.strip()[0].isupper()
        value -= 0.30 * (not token[:1].isspace())
    elif word == 'essays':
        value = 0.88
    elif word in BLOG_WORDS:
        value = 0.22 if word == 'blogging' else 0.14
        value *= 1.0 if token[:1].isspace() else 0.4
    elif token.startswith('\t') and token.isspace():
        spaces = token.count(' ')
        if spaces == 0:
            value = -0.045 if len(token) == 1 else 0.0
        elif spaces <= 2:
            value = 0.06 * spaces
        else:
            value = 0.10 * (min(spaces, 7) - 2)
            value += 0.03 * max(0, min(spaces - 7, 8))
            value -= 0.025 * max(0, min(spaces - 23, 8))
        if after_newline and spaces:
            value -= 0.10
        if '\n' in token:
            value *= 0.55
        if token.startswith('\t\t'):
            value *= 0.70
    elif token and token == ' ' * len(token):
        width = len(token)
        if width <= 2:
            value = 0.0
        elif width <= 7:
            value = -0.02 if width <= 4 else -0.04
        elif after_newline:
            value = 0.03 if 10 <= width <= 20 else -0.04
        else:
            value = 0.027 * min(width - 5, 9)
            # Adjust for incomplete four-column blocks.
            if width % 4 == 3:
                value -= 0.10
            elif width % 4 == 1:
                value -= 0.035
    return None, float(value)

programs.haiku:
"""Indentation whitespace, and the words essay and blog.

Component layers.0.mlp.down_proj:969 responds to indentation. Its strongest response is to
a single whitespace token made of a tab followed by a run of spaces (mixed tab and space
indentation, as in code or numbered listings): the activation rises by about 0.1 for each
space past the second, and levels off near 0.75 from about 10 spaces on. A run of many plain
spaces gives a weaker response, and a lone tab is slightly negative. The words "essay" and
"blog" also switch it on, the first strongly.
"""

READS = ()

SATURATION = 0.75       # activation for a long tab-then-spaces indent
PER_SPACE = 0.1         # rise per space beyond two
PLAIN_SPACES = 0.2      # a run of 12 or more plain spaces
LONE_TAB = -0.05
WORDS = {"essay": 1.0, "blog": 0.2}


def indent_value(token):
    if token == "\t":
        return LONE_TAB
    if token[:1] == "\t" and token[1:].strip(" ") == "":
        spaces = len(token) - 1
        return min(SATURATION, PER_SPACE * max(0, spaces - 2))
    if token.strip(" ") == "" and len(token) >= 12:
        return PLAIN_SPACES
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    value = indent_value(token)
    if value == 0.0:
        value = WORDS.get(token.strip().lower(), 0.0)
    return None, float(value)

programs.luna:
"""Recognize code indentation and a few writing-related words.

A tab followed by spaces is the strongest recurring cue: the predicted
activation grows with the indentation width, then levels off. Essay, blog,
and writing tokens receive a smaller typical positive activation; other
text is predicted to contribute approximately zero.
"""

READS = ()

WRITING_WORDS = {"essay", "blog", "writing"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]

    if "\t" in token and not token.strip(" \t"):
        spaces = token.count(" ")
        return None, 0.5 * min(0.79, 0.29 + 0.032 * spaces)

    if token.strip().casefold() in WRITING_WORDS:
        return None, 0.35

    return None, 0.0

programs.sol:
"""Negative pulses on the -ind spelling family, strongest on bind and hind.

Mind/wind and kind/blind are intermediate; find is weaker. Common
inflections preserve a reduced pulse, while longer words usually dilute
it. The following 'of' or a separate grammatical ending can echo it.
Smaller pulses cover -ound words, assistant, and several Chinese words
for finding, wind, binding, and India; sort/hide and 'md' also respond.
Most other tokens predict zero. Case and punctuation adjust a few roots.
"""
READS = ()
ROOT_STRENGTH = {
    'bind': 5.5,
    'hind': 6.0,
    'mind': 4.2,
    'wind': 4.4,
    'kind': 3.2,
    'blind': 3.6,
}
INFLECTIONS = {'s', 'ing', 'ings', 'ed', 'er', 'ers'}


def pulse(token):
    bare = token.strip().lstrip('._-/(\\[\"\'')
    word = bare.lower()
    if word == 'assistant':
        return -0.3 if token.startswith(' ') else -0.69
    if 'ind' in word:
        if word.startswith(('index', 'indic', 'indeed', 'industr')):
