        return -0.3
    if word in ('nd', 'und', 'ound') and not token.startswith(' '):
        return -0.55
    if word in ('sound', 'bound', 'wound', 'sort', 'hide', 'hidden'):
        return -0.85
    if word in ('sounds', 'bounds', 'wounds', 'found'):
        return -0.4
    if word == 'md':
        return -0.42
    if word in ('风', '風', '找', '寻找', '印'):
        return -1.1
    if word in ('找到', '找出', '寻', '尋'):
        return -0.55
    if word in ('绑', '綁', '印度'):
        return -2.5
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    document = prefix.document_ids[-1]
    previous = 0.0 if carry is None or carry[0] != document else carry[1]
    base = pulse(token)
    value = base
    if previous < -2.0:
        if token == ' of':
            value = 0.25 * previous
        elif token.lower() in ('s', 'ing', 'ings', 'ed'):
            value = 0.43 * previous
        elif token.lower() in ('er', 'ers', 'ful', 'fulness'):
            value = 0.30 * previous
        elif token.lower() in ('en', 'ly', 'ness', 'able'):
            value = 0.15 * previous
    return (document, base), float(value)

