programs.sol:
"""A negative en-dash response that weakens with repetition.

The leading-space en dash has a stronger response than the unspaced one.
Responses fade later in a document, and a recent previous en dash reduces
another dash's magnitude. Sharing a token with a newline, letters, or a
period scales the dash response down. Other tokens are nearly silent, except for the
Unicode hyphen. Small fixed responses also distinguish curly from straight
apostrophe word endings, em dashes, curly quotes, and the half-fraction sign.
Document boundaries reset the punctuation history.
"""

from math import log1p, sqrt

READS = ()
ENGLISH_ENDINGS = {"s", "t", "re", "ve", "m", "ll", "d"}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        position, count, last_dash = 0, 0, None
    else:
        _, position, count, last_dash = carry

    token = prefix.token_strings[-1]
    value = 0.0
    if '–' in token:
        spaced = token.startswith(' ')
        value = -4.38 - 0.44 * spaced
        value += 0.25 * log1p(position) + 0.18 * log1p(count)
        if last_dash is None:
            value += 0.13 - 0.51 * spaced
        else:
            value += 2.65 / sqrt(position - last_dash + 1)
        if '\n' in token:
            value *= 0.45
        elif any(c.isalpha() for c in token):
            value *= 0.6
        elif token.startswith('.'):
            value *= 0.8
        count += token.count('–')
        last_dash = position
    elif token == '‐':
        value = -0.59

    elif token == '½':
        value = -0.63
    elif '—' in token:
        value = 0.15
    elif token.startswith('’') and token[1:].isalpha():
        value = -0.14 if token[1:].lower() in ENGLISH_ENDINGS else -0.35
    elif token.startswith("'") and token[1:].lower() in ENGLISH_ENDINGS:
        value = 0.11
    elif token.strip() in {'“', '”'}:
        value = 0.08

    return (doc, position + 1, count, last_dash), float(value)

