    "effort", "efforts", "endeavor", "endeavors", "intend", "intends", "intended",
    "intent", "intention", "intentions", "tried", "tries", "seek", "seeks", "sought",
    "seeking", "strive", "striving", "努力", "意图", "尝试", "欲",
}

