WEAK = {
    "try", "trying", "desire", "desired", "desires", "want", "wants", "wanted",
    "request", "requests", "requested", "offer", "offers", "offered", "opportunity",
    "claim", "claims", "claimed", "alleged", "aim", "aims", "wish", "hope", "hoped",
    "threat", "seem", "seems", "seemed", "appear", "appears", "appeared", "suggest",
    "suggested", "suggests", "retry", "success", "successful", "approach", "potential",
    "idea", "goal", "pursue", "pursuit", "demand", "demands", "promise", "promised",
    "想要", "希望", "请求",
}

# Words that name the goal after a trying word.
AFTER = {"to", "at", "of", "for", "towards", "toward", "into"}


def strength(word):
    if word in STRONG:
