"""Respond to a token immediately after a fragment ending in m.

Short fragments give stronger responses than long words. Continuations
beginning n, in-, or en- are strongly positive; front vowels are moderately
positive. Back-vowel continuations can be negative. This spelling heuristic
omits the component's more idiosyncratic token-specific responses.
"""
import unicodedata

READS = ()
M_LETTERS = 'mмمมम'
TRANSLITERATE = str.maketrans({
    'е': 'e', 'ё': 'e', 'э': 'e', 'и': 'i', 'і': 'i',
    'н': 'n', 'о': 'o', 'а': 'a', 'у': 'u', 'м': 'm',
    'р': 'r', 'л': 'l', 'с': 's', 'т': 't', 'й': 'y',
    'ن': 'n', 'ی': 'i', 'ي': 'i', 'ا': 'a', 'و': 'u',
    'น': 'n', 'ี': 'i', 'ั': 'a', 'า': 'a',
    'न': 'n', 'ि': 'i',
})


def syllable_response(token):
    text = token.lower().translate(TRANSLITERATE)
    text = ''.join(c for c in unicodedata.normalize('NFD', text)
                   if unicodedata.category(c) != 'Mn')
    if not text:
        return 0.0
    if text[0].isspace():
        return 0.22 if text.lstrip().startswith(('n', 'in', 'en')) else 0.02
    if text in ('2', '3', '²', '³'):
        return 0.30
    if not text[0].isalpha():
        return 0.03

    first = text[0]
    value = (0.65 if first == 'e' else 0.55 if first == 'i' else
             1.80 if first == 'n' else 0.25 if first == 'a' else
             0.0 if first == 'o' else -0.20 if first == 'm' else
             -0.15 if first in 'cfhd' else 0.30 if first in 'rly' else
             0.40 if first == 'g' else 0.15)
    if text[1:2] == 'n':
        value += 0.70
        if first in 'ei':
            value += 0.50
    if text[2:3] == 'n':
        value += 0.20
    if text in ('e', 'i') or text.startswith(('et', 'it', 'ie', 'ia')):
        value += 0.25
    if text.startswith(('ark', 'arc', 'arg', 'ang', 'anch')):
        value += 0.60
    if text.startswith('on'):
        value += 0.45
    if text.startswith(('os', 'ot', 'om', 'od', 'oe', 'oy', 'us', 'um')):
        value -= 0.35
    if text == 'ing':
        value -= 0.90
    if len(text) > 5:
        value -= 0.15
    if token[0].isupper() and not token.isupper():
        value -= 0.15

    scripts = ' '.join(unicodedata.name(c, '') for c in token)
    if 'CYRILLIC' in scripts and first == 'e':
        value += 0.30
    if 'ARABIC' in scripts and first == 'i':
        value += 0.20
    if 'THAI' in scripts and text.startswith(('i', 'an')):
        value += 1.20
    return value


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    previous = carry[1] if carry and carry[0] == document else ''
    value = 0.002
    if previous.lower().endswith(tuple(M_LETTERS)):
        length = min(8, len(previous.strip()))
        gain = max(0.25, 1.22 - 0.15 * (length - 1))
        value += gain * syllable_response(token)
    return (document, token), float(value)

"""Approximate a q/Q-fragment continuation signal.

Following letters get the largest positive response after a fragment ending
in q; digits and punctuation get less. Longer q-bearing fragments contribute
less, and short repeated-q fragments are suppressed. Quantum-software names,
quarks and quaternions have stronger continuation responses. There is also a
small spelling-only term. At a document's start, q-bearing tokens instead get
a negative response that shrinks with length; an initial ## gets 0.8.

The rounded rules capture large q-related responses, not the many weak,
lexically specific responses elsewhere.
"""
READS = ()


def spelling(text):
    word = text.strip().lower()
    q = word.find('q')
    if q < 0:
        return 0.0
    if q > 0:
        return -0.18 if len(word) <= 4 else -0.03
    if word == 'q':
        return 0.2 if text.strip().isupper() else 0.12
    if not word.startswith('qu'):
        return 0.6
    return 0.04


def continuation(previous, text):
    p = previous.lower()
    q = p.rfind('q')
    if q < 0:
        return 0.0
    tail = p[q + 1:]
    word = text.strip().lower()
    if tail:
        # A completed word rarely transfers much to the next word.
        if text != text.lstrip() or len(tail) > 4:
            return 0.0
        if 'q' in word:
            return -0.45
        if text.isascii() and text.isalpha():
            if tail == 'u':
                if word.startswith('ark'):
                    return 0.6
                if word.startswith('atern'):
                    return 1.15
                return 0.12 if q == len(p) - len(p.lstrip()) else -0.02
            return 0.18
        return 0.0
    if 'q' in word:
        if word.startswith('q') or len(word) <= 4:
            return -1.0 - spelling(text)
        return 0.3
    if text.isalpha() and (text.isascii() or text.islower()):
        letters_before_q = sum(c.isalpha() for c in p[:q])
        scale = 1.0 if previous.endswith('Q') else 1.0 / (1 + letters_before_q)
        # Qiskit, quantum ML, Qibo, OpenQASM and QuTiP spellings.
        if word.startswith(('isk', 'ml', 'ibo', 'asm', 'utip')):
            return 3.6 if word.startswith('ml') else 3.15
        if word.startswith(('ua', 'ue')):
            return -0.25 * scale
        if word.startswith('u'):
            return 1.1 * scale
        if text.isupper():
            return 1.5 * scale
        if text.istitle():
            return 1.1 * scale
        amount = 1.4 if len(text) == 1 else 2.1 if len(text) <= 3 else 1.7
        if not text.isascii():
            amount = 1.6
        return amount * scale
    if text.isascii() and text.isdigit():
        return 0.7
    if text and text[0].isspace():
        return 0.2
    # Equality-assertion macros, such as assert_eq!(...).
    if previous.strip().lower().endswith('eq') and text.startswith('!'):
        return 0.8
    return 0.2


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = prefix.token_strings[-1]
    start = carry is None or carry[0] != doc
    previous = '' if start else carry[1]
    value = spelling(text) + continuation(previous, text)
    if start and 'q' in text.lower():
        word = text.strip()
        value = -2.4 / (1 + 0.5 * (len(word) - 1))
        if text[0].isspace():
            value *= 0.7
    elif start and text == '##':
        value = 0.8
    return (doc, text), float(value)

