READS = ()


def forms(verbs):
    """Common regular English verb inflections."""
    result = set()
    for word in verbs.split():
        root = word[:-1] if word.endswith('e') else word
        if word.endswith('y'):
            result.update((word, word[:-1] + 'ies', word[:-1] + 'ied',
                           word + 'ing'))
        else:
            result.update((word, word + 's', root + 'ed', root + 'ing'))
    return result


COPULAS = set('is are was were be been being become becomes became becoming'.split())
OBJECT_VERBS = forms(
    'determine obtain return include contain provide describe define indicate '
    'show specify create introduce call require'
) | set('find finds found finding give gives gave given giving'.split())
REPRESENTATION_VERBS = forms('represent constitute') | {'denotes'}
PREDICATE_ADVERBS = set(
    'actually really essentially literally precisely exactly indeed '
    'always usually often probably certainly sometimes mostly still virtually'.split()
)
PLACE_PURPOSE = {'at', 'for'}
COMPLEMENT_PREPOSITIONS = set('to with into about among including'.split())
CORE_PREPOSITIONS = set(
    'of in from on by between under during around near via using'.split()
)
PATH_PREPOSITIONS = set(
    'through over across before after along against throughout'.split()
)
PREPOSITION_GROUPS = (
    (PLACE_PURPOSE, 2.33), (COMPLEMENT_PREPOSITIONS, 2.10),
    (CORE_PREPOSITIONS, 1.83), (PATH_PREPOSITIONS, 1.65), ({'within'}, 1.37),
)
POSSESSIVES = set('my your our his her their its'.split())


def article_after(previous, earlier):
    word, before = previous.strip().lower(), earlier.strip().lower()
    after_be = before in COPULAS or before in {"'s", '’s', "'re", '’re'}
    if word in COPULAS:
        value = 4.5 if word in {'are', 'were'} else 4.8
        return value + (0.6 if before in {'this', 'these', 'that', 'those'} else 0.0)
    if word in {"'s", '’s', "'m", '’m', "'re", '’re'}:
        return 4.0
    if word in {'not', "'t", '’t'}:
        return 4.7 if after_be else 3.5
    if word == 'as':
        return 3.15
    if word == 'like':
        return 2.5
    if word in REPRESENTATION_VERBS:
        return 3.15
    if word in OBJECT_VERBS:
        return 2.25
    if word in {'have', 'has', 'had', 'having'}:
        return 2.1
    if word in PREDICATE_ADVERBS or word == 'just':
        return (3.2 if word == 'just' else 2.9) + (1.1 if after_be else 0.0)
    if word == 'also':
        return 3.45 if after_be else 1.65
    if word == 'only':
        return 2.75 if after_be else 1.95
    for words, value in PREPOSITION_GROUPS:
        if word in words:
            return value
    if word == 'than':
        return 1.95
    if word == 'and':
        return 0.04
    if word in {'but', 'so', 'then'}:
        return 0.3
    if word in {'that', 'which', 'because', 'while', 'although', 'though', 'wherein'}:
        return 0.6
    if word in {'if', 'when', 'where', 'whether', 'since', 'until', 'or'}:
        return 0.96
    if word in {'maybe', 'perhaps', 'how', 'what', 'why', 'all', 'even'}:
        return 1.15
    if word in {'up', 'down', 'out', 'off'}:
        return 0.95
    if ',' in word or ';' in word:
        return 0.04
    if not word or '\n' in previous or word[-1:] in {'.', '!', '?'}:
