"""Component layers.0.mlp.down_proj:986: a "the" detector whose strength is set by the word before it.

It fires on the English article " the" (and " THE"), the determiner that opens a noun phrase.
How hard it fires depends on the word just before it:
  - after a copula / linking verb (is, was, are, be, been, am, 's, not, become) it fires hardest (~4.5);
  - after "as" it fires strongly (~3.2);
  - after most other words (verbs and prepositions such as of, in, on, from, by, use, see) it fires
    moderately (~1.6), and after to, at, for, into, about, with, than a little more (~2.0);
  - after a conjunction or clause word (that, which, if, when, because, but, or, so, ...) it is weak (~0.6);
  - after "and", a comma, a semicolon or a closing bracket it is zero.
Possessive determiners (your, our, my, its, his, their, her) fire at ~3 only right after a
copula ("is your", "was our"), and zero otherwise. Every other token predicts 0.
"""

READS = ()

COPULA = {"is", "was", "are", "be", "been", "being", "am", "were", "'s", "’s", "'re", "not",
          "become", "becomes", "became"}
AS = {"as"}
NONE = {"and", ",", ";", ")", "),", ".", ":"}
CLAUSE = {"that", "which", "because", "but", "so", "then", "if", "when", "since", "although",
          "where", "while", "perhaps", "maybe", "or"}
TO_AT = {"to", "at", "for", "into", "about", "with", "than"}
THE = {" the", " THE"}
POSSESSIVE = {" your", " our", " my", " its", " his", " their", " her"}


def step(carry, prefix, upstream):
    cur = prefix.token_strings[-1]
    prev = ""
    if prefix.position > 0 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2].strip().lower()
    if cur in THE:
        if prev in COPULA:
            return carry, 4.5
        if prev in AS:
            return carry, 3.2
        if prev in NONE:
            return carry, 0.0
        if prev in CLAUSE:
            return carry, 0.6
        if prev in TO_AT:
            return carry, 2.0
        return carry, 1.6
    if cur in POSSESSIVE and prev in COPULA:
        return carry, 3.0
    return carry, 0.0

