"""A lexical brevity/detail signal, strongest on the spelling 'brief'.

Negative values mark brief/briefly (including split inflections), then weaker
families for limited duration, small degree, rapidity and descriptive detail.
There is also weaker spillover to similar spellings and official titles.
This is lexical, not a judgment about the passage: legal briefs also match.
Other tokens receive zero rather than an estimate of background activity.
"""

import re

READS = ()

# These sets name ordinary lexical concepts, not tokenizer IDs.
DETAIL = {
    'detail', 'detailed', '详细', '詳細', '详细的', '詳', '详', '詳しく', 'подроб',
}
DESCRIPTION = {'thorough', 'comprehensive', 'overview', 'explicit', 'schematic'}
CONCISE = {'concise', 'succinct', 'abbreviated', '简介', '简', '大致', 'breve'}
SMALL_DEGREE = {'slightly', 'slightest', 'roughly', 'closely', 'lightly',
                'gently', 'faint', 'vaguely', 'loosely', '稍微', '微微'}
DEGREE_OR_SCOPE = {'gentle', 'mild', 'vague', 'rough', 'broad', 'broadly', 'precise'}
TIME_OR_FREQUENCY = {'fleeting', 'shortly', 'overnight', 'occasional', 'intermittent'}
RAPID = {'rapid', 'rapidly', 'apid', '迅速'}
OFFICIAL = {'official', 'unofficial', 'officially'}
SIMILAR_SPELLINGS = {'chief', 'chiefs', 'grief'}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != document else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()

    if word == 'brief':
        value = -7.65
    elif word == 'briefly':
        value = -6.5
    elif token.lower() == 'ly' and previous.endswith('brief'):
        value = -7.1
    elif token.lower() == 's' and previous.endswith('brief'):
        value = -5.8
    elif token.lower() in {'e', 'en', 'est'} and previous.endswith('brief'):
        value = -2.1
    elif word == 'rief':
        value = -4.0
    elif word == 'briefing':
        value = -3.3
    elif word == 'ef' and previous == 'bri':
        value = -1.5
    elif word == '略':
        # In 'strategy' (战略/戰略), this character is not the 'brief' sense.
        value = -0.5 if previous.endswith(('战', '戰')) else -2.1
    elif word == 'slight':
        value = -2.4
    elif word in DETAIL:
        value = -1.4
    elif word == 'details':
        value = -0.45
    elif word in RAPID:
        value = -1.4
    elif word in CONCISE or word in SMALL_DEGREE:
        value = -1.05
    elif word in OFFICIAL or word in SIMILAR_SPELLINGS:
        value = -1.0
    elif word in DEGREE_OR_SCOPE or word in TIME_OR_FREQUENCY:
        value = -0.75
    elif word in DESCRIPTION:
        value = -0.5
    elif word in {'short', 'quick', 'broader', 'quickly', 'thoroughly'}:
        value = -0.4
    elif token.lower() == 'ly' and previous in SMALL_DEGREE | DEGREE_OR_SCOPE | RAPID:
        value = -1.1
    else:
        value = 0.0

    # Keep the unfinished word so split spellings (B + RI + EF) work too.
    joined = previous + token.lower() if token[:1].isalpha() else token.lower()
    tail = re.search(r'[a-z战戰]+$', joined[-32:])
    return (document, tail.group() if tail else ''), value

