    ('console', '.log'): .95, ('system', '.out'): 1.3,
    ('path', '.join'): 1.2, ('testing', '.T'): 1.5,
    ('fmt', '.Printf'): .7, ('std', '::'): .75,
    ('usr', '/local'): 1.05, ('dev', '/null'): 1.07,
    ('test', '/java'): 1.1, ('main', '/java'): .65,
    ('tests', '/test'): .8, ('src', '/main'): .55,
