text align;border width;stroke width;line height""")


def score(word, before, s, previous_token):
    """Fitted strengths for recognizable kinds of compound completion."""
    if len(s) == 1 and '\u3400' <= s <= '\u9fff':
        if s in '器机機箱室院館站柜櫃盒框':
            return 0.58
        if s in '人者员員師师长長':
            return 0.36
        if s in '性化式量率力度型':
            return 0.43
        relational = ('面线線图圖品物件表群组組部区區源'
                      '语語法级級层層学學数數')
        if s in relational:
            return 0.37
    head = word.lstrip('_-.')
    pair = before + ' ' + head
    if pair in STRONG_CLOSED and s.isascii() and s.isalpha():
        return 4.06 if s.islower() else 2.34
    if pair in CLOSED and s.isascii() and s.isalpha():
        return 2.34
    if s.startswith('-') and pair in CSS:
        return 2.71
    if pair in STRONG_TERMS:
        return 2.73
    if pair in TERMS:
        return 1.7
    if pair in WEAK_TERMS:
        return 0.77
    if s[:1].isspace():
        if word in PARTICLES:
            return 0.27
        if word in MEASUREMENTS:
            return 0.19
        if word in COMMON_PHRASE_HEADS:
            return 0.29
        if word in TECHNICAL_NOUNS:
            return 0.19
    elif previous_token and previous_token[-1].isalpha():
        if s in {'less', 'ful', 'proof'}:
            return 1.23
        if s in {'hood', 'ship'}:
            return 1.17
        if s in {'ness', 'ism', 'ist', 'ize', 'ization'}:
            return 0.33
        if s in {'ward', 'wards', 'worth'}:
            return 0.48
        if s in {'ing', 'ed', 's'}:
            return -0.08
        if s.isascii() and s.isalpha() and word in HEADS:
            if s[0].isupper():
                return 0.62
            return 1.64 if before in MODIFIERS else 0.96
        if s.startswith('_') and s[1:].isalpha():
            return 0.65 if head in IDENTIFIER_NOUNS else 0.13
        if s.startswith('-') and s[1:].isalpha() and len(s)>2:
            return 0.39
        if s in ('.log', '.out'):
            return 0.58
        if s in ('.com', '.org', '.net', '.js', '.json', '.py', '.md', '.go'):
            return 0.25
    return 0.02


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        tail, previous = '', ''
    else:
        _, tail, previous = carry
    # The last CamelCase part also counts as a word (PhpSpread -> Spread).
    match = re.search(r'[A-Z]?[a-z]+$|[A-Z]+$', tail)
    before = match[0].lower() if match else ''
    value = CODE_PAIRS.get((before, s),
                           score(s.strip().lower(), before, s, previous))
    if s.isascii() and s.isalpha() and previous and previous[-1].isalpha():
        tail = (tail + s)[-80:]
    else:
        match = re.search(r'[A-Za-z]+$', s)
        tail = match[0] if match else ''
    return (doc, tail, s), float(value)

