"""Layer 0, MLP down-projection, hidden unit 992: a "divide / split / pick one of several"
word detector.

The component writes into the residual stream only when the current token is a word about
dividing things into parts, separating, or choosing between alternatives. The strongest
responses are the Chinese/Korean character for "divide" (分, 분) and the English "split" and
"separate"; the most frequent one is the disjunction " or" (about 0.8 everywhere it occurs,
in any context). Other words of the same kind (else, different, part, various, portion,
section, fraction, distribution, segment, parse) give a smaller, steady response. Any other
token predicts 0.

The program is a lookup of the current token alone; it keeps no state across positions.
"""

from collections.abc import Mapping

READS = ()

# Disjunction: "X or Y", "or else".
OR_WORDS = {" or", " Or", " OR", "或", " или"}

# Clear "else" alternatives.
ELSE_WORDS = {" else", "\telse"}

# Chinese / Korean "divide" characters: the strongest responses.
DIVIDE_CHARS = {"分", "分别", "분"}

# Splitting and separating.
SEPARATE_WORDS = {
    " separate", " separately", " separation", " split", "split", ".split", " splitting",
    " segmentation", " separ",
}

# Parts, portions, sections, fractions, and kindred words of dividing or distinguishing.
PART_WORDS = {
    " part", " parts", " partition", " partial", " apart", " portion", " section", " sections",
    " Section", " subsection", " fraction", " fractions", " frac", "frac", " segment",
    " segments", " division", " Division", " divide", " divided", " distribution",
    " distributed", " distribute", " branch", " branches", " break", " breaks", " breaking",
    " broken", " various", " different", " differently", " difference", " distinct",
    " respective", " respectively", " individual", " percentage", " percentages",
    " denominator", " piece", " pieces", " Parse", "Parse", " parse", "parse", " Parser",
    "Parser", " parser", ".parse", " раздел", " различ", "拆",
}

WEIGHTS = {}
for _t in OR_WORDS:
    WEIGHTS[_t] = 0.8
for _t in ELSE_WORDS:
    WEIGHTS[_t] = 0.5
for _t in PART_WORDS:
    WEIGHTS[_t] = 0.8
for _t in SEPARATE_WORDS:
    WEIGHTS[_t] = 1.6
for _t in DIVIDE_CHARS:
    WEIGHTS[_t] = 4.5


def step(carry, prefix, upstream: Mapping):
    """The component's activation at this position: the weight of the current token."""
    return carry, float(WEIGHTS.get(prefix.token_strings[-1], 0.0))

