    'χ': (0.85, -0.10), 'ψ': (0.73, 0.50), 'ω': (0.89, -0.18),
    'ϕ': (0.75, 0.23), 'ϵ': (0.78, 0.00),
    'Α': (1.30, 1.05), 'Β': (2.30, 2.35), 'ά': (0.50, 0.50),
    'Γ': (1.15, 1.15), 'Δ': (0.60, 0.10), 'Θ': (1.15, 0.60),
    'Λ': (0.85, 0.35), 'Π': (0.27, 0.03), 'Σ': (0.15, 0.10),
    'Φ': (0.75, 0.50), 'Ψ': (0.50, 0.50), 'Ω': (0.46, 0.46),
