    'alpha': (1.25, 1.55), 'beta': (1.90, 2.18),
    'gamma': (1.40, 1.65), 'delta': (0.43, 0.70),
    'epsilon': (0.47, 0.70), 'zeta': (0.45, 0.78),
    'eta': (0.29, 0.94), 'theta': (0.90, 1.30),
    'iota': (0.10, 0.45), 'kappa': (0.57, 0.90),
    'lambda': (0.90, 1.07), 'mu': (0.18, 0.76),
    'nu': (0.02, 0.65), 'xi': (0.00, 0.66),
    'pi': (0.03, 0.47), 'rho': (0.35, 0.69),
    'sigma': (0.50, 0.66), 'tau': (0.15, 0.73),
    'upsilon': (0.15, 0.60), 'phi': (0.47, 0.89),
    'chi': (0.04, 0.73), 'psi': (0.21, 0.61),
    'omega': (0.40, 0.69),
