        name = text.lstrip('_=.(/-').lower()
        if name in NAMES:
            tex = previous.endswith('\\')
            value = NAMES[name][int(tex)]
            if text[:1].isupper():
                value *= 0.75 if name in {'gamma', 'delta', 'sigma'} else 0.90
