"""Give conservative estimates for a few rare notation cues.

Greek letters, superscript or subscript characters, literal tabs, and
ordinary digits after a caret get small positive estimates.  Everything
else gets zero; these are broad text cues, not a reconstruction of the
model's internal computation.
"""
import unicodedata

READS = ()


def _greek(ch):
    name = unicodedata.name(ch, "")
    return "GREEK" in name and unicodedata.category(ch).startswith("L")


def step(carry, prefix, upstream):
    strings = prefix.token_strings
    token = strings[-1]
    core = token.strip()

    if token == "\t":
        return None, 0.11
    if len(core) == 1 and _greek(core):
        return None, 0.31
    if len(core) == 1:
        name = unicodedata.name(core, "")
        if "SUPERSCRIPT" in name or "SUBSCRIPT" in name:
            return None, 0.23

