    if word == '自':
        return -9.8 if token == '自' else -7.7
    if '自' in token:
        if token in STRONG_SELF_COMPOUNDS:
            return -3.8
        if token in {'自动', '自動', '自行'}:
            return -3.1
        if '自己' in token or token.startswith('自分'):
            return -1.9 if len(token) == 2 else -1.2
        return -2.5 if len(token) == 2 else -1.4
    if word == '白':
        return -1.2
    if word == 'self':
        if token[0] in '(:[<=':
            return -2.0 if 'Self' not in token else -2.7
        return -2.85 if 'Self' not in token else -3.4
    if word in REFLEXIVES:
        return -1.1
    if word in {'elves', 'elf'}:
        return -1.4
    if word in {'shelf', 'shelves'}:
        return -0.6
    if word in {'selves', 'selfish', 'selfless'}:
        return -1.9
    if word in SELF_TRANSLATIONS:
        return -2.2
    if word in {'сам', 'себя', 'себе', 'самостоятельно', '자', '자신'}:
        return -2.8 if token == ' 자' else -1.1
    if word == 'from':
        if token == ' from' or token.upper() == token:
            return -0.48
        return -0.8 if 'From' in token else -1.0
    if word in ORIGIN_WORDS:
        return -0.4
    if word in {'从', '從', '由'}:
        return -1.0
    if (word == 'aut' or word.startswith(('auto', 'autis'))
            or word == 'autumn'):
        if word == 'aut':
            return -2.7 if token[:1].isspace() or 'Aut' in token else -1.5
        if word.startswith('automatic'):
            return -2.3 if word.endswith('ally') else -3.0
        if word.startswith('autour'):
            return 0.0
        if word in {'auto', 'autoc', 'autof', 'autob', 'autoimmune'}:
            return -2.6
        if word == 'autom':
            return -2.0
        return -1.5
    if word.startswith('custom') and not word.startswith('customer'):
        return -0.9 if word == 'customized' else -1.6
    if word in {'natural', 'naturally', 'natur', 'atural'}:
        return -1.35 if word == 'natural' else -0.85
    if word.startswith('автомат'):
        return -1.6 if word == 'автомат' else -1.1
    if word.startswith(('авто', 'само')) or word == '자기':
        return -1.5
    if word in {'spontaneous', 'spontaneously', 'masturbation', 'masturb'}:
        return -1.4
    if word in {'mutual', '互相', '互'}:
        return -1.0
    if word in {'already', 'bereits'}:
        return -0.3
    return 0.0


CODE = re.compile(r"\b(?:def|fn|let|return|import|assert|elif)\b|self[.(]|[{};=]")
SEPARATION = {'away', 'apart', 'aside', 'far', 'different', 'differ',
              'differs', 'separate', 'separated', 'distinct'}


