programs.sol:
"""A negative indentation/whitespace response, not a response to code words.

Separate space runs at the start of a real line have a strong negative value;
inline runs are much weaker. A lone tab beginning a line is strongest, while
additional tabs and mixed tab/space tokens are weaker. Width-specific levels
calibrate these tokenized whitespace forms. Ordinary tokens predict zero.
State records line indentation and resets at every document boundary.
"""
READS = ()


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        blank, column, position = True, 0, 0
    else:
        _, blank, column, position = carry
    s = prefix.token_strings[-1]
    width = len(s)
    value = 0.0
    if s and s.isspace():
        tabs, spaces = s.count('\t'), s.count(' ')
        if '\n' in s or '\r' in s:
            if tabs:
                value = -1.04 if blank else -0.82
            elif spaces >= 2 and blank:
                value = -min(1.1, 0.40 + 0.022 * spaces)
        elif not s.strip(' '):
            if width == 1:
                value = -1.05 if column == 0 and position else 0.01
            elif blank:
                if width == 2:
                    value = -0.92
                elif width == 3:
                    value = -1.42
                elif width == 7:
                    value = -1.56
                elif width in (11, 15):
                    value = -1.40
                else:
                    value = -0.97 if width < 16 else -1.45
            elif width % 4 == 3:
                value = -0.46 if width < 8 else -0.35
            elif width % 4 != 0:
                value = min(0.25, 0.02 * width)
        elif not s.strip('\t'):
            if width == 1:
                if blank and column == 0 and position:
                    value = -4.60 - (0.60 if position < 15 else 0.0)
                elif blank:
                    value = -3.33 if column == 1 else -3.0
                else:
                    value = -3.05
            elif blank:
                value = -2.90 if width in (2, 5) else -2.55
            else:
                value = -1.52 if width == 2 else -1.30
        elif tabs:
            if blank:
                value = -1.85
            elif spaces <= 3:
                value = -0.97
            elif spaces == 9:
                value = -0.08
            else:
                value = -0.55 if spaces >= 19 else -0.43
    if '\n' in s:
        tail = s.rsplit('\n', 1)[-1]
        blank, column = not tail.strip(), len(tail)
    else:
        blank = blank and not s.strip()
        column += width
    return (doc, blank, column, position + 1), float(value)

