"""Indentation: whitespace-only tokens (tabs and runs of spaces) at the start of a line of code.

The component is strongly negative on indentation whitespace in code, and near zero on
everything else. Its value at a whitespace-only token depends on what the token is and where
it sits:

- a tab run at the start of a line gives about -4.5 (a single tab) or -2.8 (several tabs);
  a tab run in the middle of a line about -3.2;
- a tab followed by spaces, or whitespace ending in a newline, gives a moderate -0.8;
- a run of spaces at the start of a line gives about -1.0, a little more (-1.5) when the run
  has 3, 7, 11, ... spaces; a single space at a line start about -1.1;
- spaces in the middle of a line give about -0.4 (a single one about 0);
- anything that is not pure whitespace gives 0.

"Start of a line" means the previous token ends a line with a newline, or is the first token
of a document (documents reset the context, as in the model).
"""
READS = ()


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    if not tok or set(tok) - set(" \t\n\xa0"):
        return carry, 0.0  # not a pure whitespace token
    tabs = tok.count("\t")
    spaces = tok.count(" ") + tok.count("\xa0")
    new_doc = prefix.position == 0 or prefix.document_ids[-1] != prefix.document_ids[-2]
    line_start = new_doc or "\n" in prefix.token_strings[-2]
    if "\n" in tok:
        value = -0.8 if tabs else (-0.45 if spaces >= 2 else 0.0)
    elif tabs and spaces:
        value = -0.8
    elif tabs:
        value = (-4.5 if tabs == 1 else -2.8) if line_start else -3.2
    elif spaces == 1:
        value = -1.1 if line_start else 0.0
    elif line_start:
        value = -1.5 if spaces % 4 == 3 else -1.0
    else:
        value = -0.4
    return carry, float(value)

