"""Recognize formatting whitespace, especially indentation tokens."""

READS = ()


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    if not text or not all(ch in " \t\r\n" for ch in text):
        return None, -0.021

    if "\t" in text:
        if text == "\t":
            value = -3.3
        elif " " not in text and "\n" not in text and "\r" not in text:
            value = -2.6
        elif "\n" in text or "\r" in text:
            value = -0.8
        else:
            value = -0.9
    elif text.strip("\r\n") and len(text.strip("\r\n")) >= 2:
        value = -1.0
    elif text == " " and len(prefix.token_strings) > 1:
        previous = prefix.token_strings[-2]
        same_document = prefix.document_ids[-2] == prefix.document_ids[-1]
        value = -1.0 if same_document and previous.endswith(("\n", "\r")) else -0.021
    else:
        value = -0.021
    return None, float(value)

programs.sol:
"""Approximate the component's dominant Markdown-formatting response.

Two-to-six-hash tokens are negative, strongest at heading level three.
Their strength depends on the preceding token's line breaks and backticks,
and weakens with the number of earlier heading-like hash tokens in the
same document. Bold-like openings, code fences and separators have smaller
responses. Everything else is zero; document boundaries reset history.
"""
import math

READS = ()
# Heading level: response after a blank line, repetition gain, space shift.
LEVELS = {
    2: (-3.9, 0.6, -0.6),
    3: (-7.3, 0.8, 0.6),
    4: (-6.8, 0.6, -0.5),
    5: (-5.4, 0.5, -0.5),
    6: (-4.3, 0.3, 0.0),
}
# First-token responses, indexed by hash count 1 through 6.
AT_START = (-1.45, -2.27, -6.31, -3.13, -3.21, -2.37)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, count = ('', 0) if first else carry[1:]
    text = prefix.token_strings[-1]
    marker = text.strip()
    newline = previous.endswith('\n')
    blank = previous.endswith('\n\n')
    spaced = text.startswith(' ')
    value = 0.0
    if marker and set(marker) == {'#'}:
        n = len(marker)
        if first and n <= 6:
            value = AT_START[n - 1]
        elif n == 1:
            value = 0.1 if spaced else (-0.3 if blank else 0.05)
        elif n in LEVELS:
            base, gain, space_shift = LEVELS[n]
            value = base + gain * math.log1p(count)
            if not newline:
                value += 1.5
                if previous.endswith('\\n'):
                    value -= 0.8
            elif not blank:
                value += 0.6 if n == 2 else 0.3
            if spaced:
                value += space_shift
            if previous.rstrip('\n ').endswith('`'):
                value -= 1.3 if n == 3 else 0.7
            if n == 3 and previous.rstrip('\n ').endswith(('.', '?', '!')):
                value -= 0.4
            value = min(value, 0.0)
        if 2 <= n <= 6:
            count += 1
    elif marker == '**':
        if first:
            value = -0.31
        elif spaced:
            value = -1.15 if previous in {'.', '-', '  '} else -0.5
        elif newline:
            value = -1.08 if blank else -0.76
    elif marker == '```':
        value = -0.57 if blank else (-0.68 if newline else -0.51)
    elif marker == '===':
        value = -0.3 if spaced else (-1.02 if newline else -0.59)
    elif marker == '---':
        value = -0.4 if newline else -0.13
        if text.endswith('\n\n'):
            value = -0.56 if newline else -0.15
        elif text.endswith('\n'):
            value = -0.12 if newline or first else 0.07
    return (doc, text, count), float(value)

programs.haiku:
"""Markdown heading markers (layers.0.mlp.down_proj:1006).

This component is a "Markdown heading opener" detector with a negative sign. It goes
strongly negative on the run of '#' characters that opens a Markdown heading when that run
starts a line ("\n\n### Title"), and the deeper the heading the more negative it is in the
harvest: '###' about -7, '##' about -2.5, '#' about -0.5 and '####'/'#####' about -5 to -6.
Weaker negatives come on a few other formatting tokens that mark structure: '===' (rule
lines), ' **' (bold opener), and '```' (code fence). Every other token gives 0.

The rule is written on the decoded token text and on whether the previous token ended a
line, so it is a plain reading of the text, not a copy of the model's weights.
"""

READS = ()

# Activation on a heading marker, by its number of '#' (value when it opens a line).
HEADING = {"#": -0.5, "##": -2.5, "###": -7.0, "####": -6.0, "#####": -5.0, "######": -4.5}
# Weaker formatting tokens that open a structure.
FORMAT = {"===": -1.0, "**": -0.1, " **": -0.7, "```": -0.5}
# The same heading marker in the middle of a line (e.g. " ##" after text) is much weaker.
MID_LINE_SCALE = 0.25


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous = prefix.token_strings[-2] if len(prefix.token_strings) > 1 else "\n"
    starts_line = previous.endswith("\n")
    if token in HEADING:
        return carry, float(HEADING[token] if starts_line else HEADING[token] * MID_LINE_SCALE)
    if token.startswith(" ") and token[1:] in HEADING:
        return carry, float(HEADING[token[1:]] * MID_LINE_SCALE)
    if token in FORMAT:
        return carry, float(FORMAT[token])
    return carry, 0.0

