"""Estimate the response to visible Markdown headings and formatting marks."""
READS = ()


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    mark = raw.strip()
    t = prefix.position
    starts_line = (
        t == 0
        or raw.startswith("\n")
        or (
            t > 0
            and (
                prefix.document_ids[-1] != prefix.document_ids[-2]
                or prefix.token_strings[-2].endswith("\n")
            )
        )
    )

    # Markdown heading depth: a line-start run of hashes is a strong negative cue.
    if mark and set(mark) == {"#"}:
        count = len(mark)
        if count == 1:
            if starts_line:
                return None, -0.1
            return None, 0.14 if raw.startswith(" ") else 0.02
        if count == 2:
            return None, -3.3 if starts_line else -1.15
        if count == 3:
            return None, -6.9 if starts_line else -3.6
        if count == 4:
            return None, -6.1 if starts_line else -5.6
        if count == 5:
            return None, -5.0
        return None, -1.2

    if mark == "**" and (raw.startswith(" ") or starts_line):
        return None, -0.75
    if mark == "***" and (raw.startswith(" ") or starts_line):
        return None, -0.45
    if mark == "___" and (raw.startswith(" ") or starts_line):
        return None, -0.45

    # Fenced code, horizontal rules, and repeated equals-sign separators.
    if mark in ("```", "~~~"):
        return None, -0.5
    if mark == "---":
        return None, -0.4 if starts_line else -0.16
    if mark == "===":
        if starts_line:
            return None, -1.0
        return None, -0.3 if raw.startswith(" ") else -0.65
    if len(mark) >= 4 and set(mark) in ({"-"}, {"="}):
        return None, -0.2 if starts_line else 0.0
    if mark == "![":
        return None, -0.6

    # An HTML emphasis tag begins immediately after its opening angle bracket.
    if mark.lower() in ("strong", "b", "em") and t > 0:
        if prefix.token_strings[-2].endswith("<"):
            return None, -0.15
    return None, 0.0

programs.haiku:
"""Completion, success and status words, strongest in logs, tool output and code.

Component layers.0.mlp.down_proj:1008 (layer 0's MLP) writes a "this step ended, or a
status is being reported" signal into the residual stream. The program predicts how
strongly it fires on the current token, from the word itself and from whether the
text just before it looks like code or terminal output rather than ordinary prose:

- completion and success words ("finished", "completed", "done", "ready", "already",
  "success", "successfully", "passed", "PASS", "ok", "✓"): strongest;
- failure words and status nouns ("failed", "error", "err", "warning", "status",
  "result", "progress", "total", "index", "state", "info", "count"): medium;
- state-change verbs of log lines ("found", "matched", "updated", "added", "loaded",
  "created", "changed", "deleted", "running", "version"...): weak;
- separators ("...", "---", "===", "##", and runs of four or more "-", "=", "*", "#", "/"):
  medium;
- "been" (as in "has been edited"): weak.

Context: "code" means one of the last ~60 characters is a code or terminal sign
({ } ( ) ; = [ ] _ < > \\ / $, a tab, a double space, "exit code", "tool_response").
The word-based strengths above are for code and logs; in prose the completion and
success words fire about half as hard, and the status nouns and state-change verbs a
third as hard, so "the success of" or "as a result" barely move it.

Document boundaries reset the context, as the model does.
"""

import re

READS = ()

COMPLETE_SUCCESS = {
    "finished", "finish", "completed", "complete", "done", "ready", "already",
    "success", "successfully", "successful", "succeeded", "passed", "pass", "pas", "ok",
    "✓", "✔", "已", "已经", "完成", "okay",
}
FAILURE_STATUS = {
    "failed", "fail", "failure", "error", "errors", "err", "✗", "warning", "warnings",
    "status", "result", "results", "progress", "total", "index", "state", "info", "count",
}
STATE_CHANGE = {
    "found", "match", "matched", "matches", "missing", "updated", "added", "loaded",
    "processed", "parsed", "elapsed", "running", "working", "version", "changes", "created",
    "modified", "deleted", "changed", "selected", "detected", "collected", "removed", "saved",
    "edited", "installed", "started", "stopped", "generated", "counted", "matching",
    "reached", "ended", "finishing", "information", "okay", "succeed", "supported",
}
SEPARATORS = {"...", "…", "---", "===", "##"}
BANNER = re.compile(r"[-=*#/_~+.]{4,}")
CODE_SIGNS = re.compile(r"[{}();=\[\]_<>\\/$]|\t|  |exit code|tool_response")
CONTEXT_CHARS = 60


def step(carry, prefix, upstream):
    """carry: the last CONTEXT_CHARS characters of the document so far (or None)."""
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        carry = None
    context = carry or ""
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    in_code = bool(CODE_SIGNS.search(context))

    if word in COMPLETE_SUCCESS:
        strength = 1.0 if in_code else 0.5
    elif word in FAILURE_STATUS:
        strength = 0.5 if in_code else 0.15
    elif word in STATE_CHANGE:
        strength = 0.3 if in_code else 0.1
    elif word in SEPARATORS or BANNER.fullmatch(word):
        strength = 0.4
    elif word == "been":
        strength = 0.25
    else:
        strength = 0.0

    return (context + token)[-CONTEXT_CHARS:], float(strength)

