"""Negative responses to short written 'at' endings and the format family.

The current token alone determines the prediction. At, cat, mat, plurals,
and format trigger negative values, calibrated for spaces and capitals.
That/what and common grammatical endings are excluded. Small branches
cover accented and Cyrillic/Arabic at-like forms and Chinese 'format'.
Unmatched tokens receive zero; context-dependent variation is omitted.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    spaced = token.startswith(' ')
    word = token.strip().lstrip('._/=-(\"\'“”')
    s = word.lower()
    value = 0.0
    if s == 'format':
        value = -2.7 if token.startswith('.') else -3.5 if spaced else -4.0
    elif s in ('formats', 'formatting', 'formatted', 'formatter', 'fmt'):
        value = -3.0 if s == 'formats' else -0.85 if s == 'fmt' else -1.6
    elif s == '格式':  # Chinese: format
        value = -2.45
    elif s == 'at':
        if word == 'AT':
            value = -2.7 if spaced else -4.2
        else:
            value = -1.8 if spaced or word == 'At' else -3.4
    elif s.endswith('ат') and len(s) <= 4:
        value = -2.4 if len(s) <= 3 else -1.8
    elif s.endswith('ات') and len(s) <= 3:
        value = -1.4
    elif s in ('át', 'ät', 'ят'):
        value = -0.9
    elif s.endswith('at') and len(s) <= 7 and s not in ('that', 'what'):
        if s in ('eat', 'seat', 'beat', 'meat', 'neat', 'coat'):
            value = -1.15
        elif s.endswith(('eat', 'oat')):
            value = -0.5 if len(s) == 4 else 0.0
        elif len(s) > 4:
            value = -1.9 if s.endswith('mat') else -1.2
        elif s in ('hat', 'flat', 'sat'):
            value = -1.65
        elif s == 'rat':
            value = -4.0
        elif s == 'aat':
            value = -2.0
        elif word.isupper():
            value = -3.4
        elif s in ('cat', 'chat'):
            value = -2.35 if spaced else -2.8
        else:
            value = -2.5 if spaced else -3.5
    elif s.endswith('ats') and len(s) <= 4:
        value = -1.95 if spaced else -3.1
    elif s == 'atted':  # doubled consonant before a past-tense ending
        value = -2.75
    elif s.startswith('at') and len(s) <= 5:
        # Common grammatical suffixes are not independent at syllables.
        if s not in ('ate', 'ates', 'ated', 'ating', 'ation', 'ative',
                     'ator', 'ators', 'ature'):
            value = -0.6
    return None, value

