# activation on the word itself
WORD = {
    "proportion": 3.5, "proportions": 2.0, "portion": 2.8, "portions": 2.0,
    "percentage": 2.2, "percentages": 1.5, "fraction": 2.2, "fractions": 1.2,
    "fractional": 1.5, "proportional": 1.2, "percent": 1.1, "%": 0.7,
    "ratio": 0.9, "ratios": 0.7, "majority": 1.4, "minority": 1.4,
    "share": 0.65, "shares": 0.65, "half": 0.8, "rest": 0.5, "cent": 0.5,
    "part": 0.3, "parts": 0.4, "piece": 0.5, "pieces": 0.5, "pair": 0.5,
    "pairs": 0.5, "segment": 0.6, "mixture": 0.6, "region": 0.4, "regions": 0.5,
    "比例": 2.5, "份额": 3.0, "占比": 1.8, "占": 1.1, "部分": 0.8, "часть": 1.2, "半": 1.0,
}

# activation on an "of" that follows the word
OF_AFTER = {
    "proportion": 5.7, "percentage": 4.5, "fraction": 4.2, "portion": 3.0,
    "percent": 2.8, "%": 1.9, "share": 2.9, "shares": 1.8, "ratio": 2.0,
    "ratios": 1.8, "portions": 2.0, "majority": 1.3, "segment": 1.5,
    "sample": 1.1, "subset": 1.2, "cent": 1.4, "rest": 1.0, "half": 0.9,
    "part": 0.8, "parts": 0.6, "component": 0.9, "blend": 0.9, "mix": 0.6,
    "concentration": 0.7, "bulk": 0.7, "extent": 0.7, "remainder": 0.75,
}
# measure, amount or subdivision nouns: a weaker "of"
MEASURE = {
    "set", "amount", "amounts", "rate", "rates", "concentration", "degree", "volume",
    "quantity", "quantities", "range", "region", "area", "section", "sections", "piece",
    "content", "distribution", "composition", "sum", "quarter", "frequency", "dose",
    "subsets", "snippet", "much", "mixture", "stock", "probability",
}
# words for a kind, count or category: a slightly negative "of"
KIND_OF = {
    "one", "all", "world", "series", "variety", "meaning", "bunch", "name", "couple",
    "kind", "sort", "purpose", "life", "lives", "game", "existence", "number", "terms",
    "lots", "form", "lack", "species", "genus", "each", "heart", "benefits", "university",
}


# other part-of-a-whole nouns: a moderate activation on the word itself
PART_NOUNS = {"population", "component", "components", "sample", "subset", "content",
              "composition", "section", "sections", "distribution", "portfolio", "snippet"}
# words that do not name a share: slightly negative on the word itself
NOT_SHARE = {"number", "value", "most", "order"}


def _word(s):
    return s.strip().lower()


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    value = WORD.get(word, 0.3 if word in PART_NOUNS else (-0.1 if word in NOT_SHARE else 0.0))
    if word == "of" and len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        before = _word(prefix.token_strings[-2])
