    return carry, float(value)

programs.sol:
"""A negative detector of symbols joined to Latin letters within one token.

+letter and *letter are strongest; words after symbols are usually weaker.
A preceding number or lone letter makes /letter, -letter and (letter more
formula-like. For /letter and -letter, uppercase or mixed-case left fragments
and common coordinate/index letters strengthen the response.
Contractions, escapes and HTML entities are handled separately. Compound
operand prefixes and a standalone + get weak responses. Other tokens get zero.
Constants summarize training examples, not a token-ID table.
Only an 80-character tail is retained, and it resets between documents.
"""
import re

READS = ()
MATH_VARIABLES = frozenset("xyzijk")  # coordinates and conventional loop indices

# Negative response to (lowercase, uppercase) letters immediately after a symbol.
LETTERS = {
    '+': (-4.05, -4.36), '*': (-2.41, -2.33), '=': (-1.85, -1.82),
    ',': (-1.58, -1.29), '&': (-2.01, -2.42), '^': (-1.56, -1.56),
    '<': (-1.34, -0.87), '>': (-1.35, -1.31), '[': (-0.91, -0.78),
    '(': (-0.62, -0.45), ')': (-0.78, -0.78), '{': (-0.43, -0.49),
    '}': (-0.41, -0.41), ':': (-1.04, -0.94), ';': (-1.20, -1.20),
    '/': (-0.65, -0.85), '-': (-0.33, -0.34), '|': (-1.69, -0.87),
    '$': (-0.95, -0.95), '%': (-1.45, -0.80), '@': (-1.47, -1.47),
}
WORDS = {
    '*': -1.33, ',': -0.80, '=': -0.42, '[': -0.43, '<': -0.32,
    '>': -0.28, ':': -0.30, ';': -0.50, '&': -0.21, '$': -0.54,
    '@': -0.13, '(': 0.08, '-': 0.03, '/': 0.08,
}


def joined_letter(symbol, letter, tail):
    upper = int(letter.isupper())
    previous = tail[-1:]
    word = re.search(r"[A-Za-z]+$", tail)
    length = len(word[0]) if word else 0
    formula = length == 1 or previous.isdigit()
    abbreviation = length > 1 and (
        word[0].isupper() or (not word[0].islower() and not word[0].istitle())
    )
    value = LETTERS.get(symbol, (0.0, 0.0))[upper]
    if symbol == '(':
        if not tail:
            value = -0.70
        elif formula:
            value = (-0.61, -0.49)[upper]
        elif previous.isspace():
            value = (-0.21, -0.06)[upper]
        elif length > 1:
            # (f often starts a Python f-string argument after a function name.
            value = 0.0 if letter == 'f' else (-0.19, -0.13)[upper]
    elif symbol in '-/':
        if formula:
            response = (-0.74, -0.67) if symbol == '-' else (-0.81, -1.14)
            value = response[upper]
        elif abbreviation:
            response = (-0.52, -0.48) if symbol == '-' else (-0.70, -0.84)
            value = response[upper]
        elif length > 1:
            response = (-0.22, -0.27) if symbol == '-' else (-0.26, -0.53)
            value = response[upper]
        if letter in MATH_VARIABLES:
            value -= 0.40 if symbol == '-' else 0.25
    elif symbol == '<':
        if formula:
            value = (-2.00, -1.47)[upper]
        elif previous.isspace():
            value = (-0.30, -0.25)[upper]
    elif symbol in "'’":
        value = 0.0 if letter in 'stm' else -0.20 if letter == 'd' else -0.50
    elif symbol == '\\':
        value = -0.15 if letter == 't' else 0.0 if letter in 'nxr' else -0.40
    elif symbol == ';':
        entity = re.search(r'&(?:#(?:x[0-9a-fA-F]+|[0-9]+)|[A-Za-z]+)$', tail)
        if entity:
            value = 0.0
    return value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    value = 0.0
    if len(token) > 1:
        symbol, rest = token[0], token[1:]
        if rest.isascii() and rest.isalpha():
            if len(rest) == 1:
                value = joined_letter(symbol, rest, tail)
            else:
                value = WORDS.get(symbol, 0.0)
        elif (symbol == '+' and not token[1].isspace()
              and not token[1].isalnum() and token[1] != '+'):
            # + attached to other punctuation, e.g. +(, +. or +/.
            scale = 0.25
            if token[1] == '\\':
                scale = 0.13
            elif token[1] == '/':
                scale = 0.35
            value = scale * LETTERS[symbol][0]
        elif symbol in '*=,&' and token[1] in '(["\\@-':
            # A compound operand prefix gives a weaker response.
            scale = 0.13 if token[1] == '\\' else 0.25
            if symbol == ',' and token[1] in '@-':
                scale = 0.33
            value = scale * LETTERS[symbol][0]
    elif token == '+':
        previous = tail[-1:]
        if previous.isalnum():
            value = -0.25
        elif not previous or previous in '\n\r':
            value = 0.11
    return (doc, (tail + token)[-80:]), float(value)

programs.luna:
"""Marks line breaks, especially ones following sentence-ending punctuation."""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if "\n" not in token and "\r" not in token:
        return None, 0.0

    text = prefix.text_prefixes[-1].rstrip("\r\n")
    line = text.rsplit("\n", 1)[-1].rstrip()
    if line.endswith((".", "!", "?", "…")):
        value = -1.4
    elif line.endswith((",", ";", ":")):
        value = -0.7
    else:
        value = -0.75
    return None, value

programs.sol:
"""Approximate strong bird/insect responses and selected weaker lexical cues.

Bird, insect and poultry labels get large negative pulses; ordinary
species names and other nature words get smaller ones. Word fragments
count too, so mamm- also matches the piece in mammography. Warm/cold/hot
or dry before weather strengthens its pulse. Thought/tool markup and
Chinese private-server terms are separate cues, not nature detectors.
Most ordinary lexical fluctuations remain unmodeled. Only the previous
word is remembered, resetting at document boundaries.
"""
READS = ()

# Sets describe familiar kinds of words, not vocabulary token identifiers.
INSECT_LABELS = {'insect', 'insects', '昆虫'}
CHINESE_BIRDS = {'鸟', '鳥', '小鸟', '鸟类'}
ANIMAL_CLASSES = {
    'livestock', 'mammals', 'dinosaur', 'dinosaurs', 'inosaur', 'osaurs',
    'rodents', 'rept', 'verte', 'cattle',
}
SMALL_FLYING_ANIMALS = {
    'bee', 'bees', 'bug', 'bugs', 'butterfly', 'mosquito',
    'duck', 'goose', 'geese', 'feather', 'feathers',
    '蝴蝶', '蝶', '鸡', '鸡肉', '鸡汤', '鸭', '鹅',
}
NATURE_TERMS = {
    'animal', 'animals', 'creature', 'creatures', 'fish', 'dog', 'dogs',
    'snake', 'snakes', 'deer', '动物', '鱼', '魚', '蛇', '狗',
}
CROPS_AND_FLOWERS = {'citrus', '花卉', '花朵', '农产品'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    value = 0.001
    if word in {'bird', 'birds'}:
        begins_lowercase_word = token.startswith(' ') and token.strip().islower()
        value = -1.1 if begins_lowercase_word else -1.3
    elif word == 'poultry' or word in CHINESE_BIRDS:
        value = -1.3
    elif word in INSECT_LABELS:
        value = -1.1
    elif word == '禽':
        value = -1.75
    elif word in {'蚊', '野生动物', '🐦', '气象'}:
        value = -0.9
    elif word in {'蜂', '蜜蜂', 'mamm'}:
        value = -0.66
    elif word == 'wildlife':
        value = -0.7
    elif word in {'chicken', 'chickens'}:
        value = -0.53 if token.strip().islower() else -0.38
    elif word in ANIMAL_CLASSES or word in {
        '虫', '蟲', '凤凰', '雀', '莺', '兽',
    }:
        value = -0.46
    elif word in {'butterflies', 'mosquitoes'}:
        value = -0.6
    elif word == 'ducks':
        value = -0.45
    elif word in SMALL_FLYING_ANIMALS:
        value = -0.3
    elif word in NATURE_TERMS:
        value = -0.14
    elif word in {'meteor', 'eteor'}:
        value = -0.58
    elif word == 'weather':
        value = -0.27
        if previous in {'cold', 'warm', 'hot', 'dry'}:
            value -= 0.17
    elif word in CROPS_AND_FLOWERS:
        value = -0.46
    elif word == '传奇私服':
        value = 1.08
    elif word == '私服':
        value = 0.7
    elif token == '</think>':
        value = 0.29
    elif token == '<think>':
        value = 0.13
    elif token == '</tool_call>':
        value = 0.08
    elif token == '<tool_response>':
        value = -0.08
    return (doc, word), value

programs.haiku:
"""Layer-0 MLP component 1014 (down_proj): a "birds and insects" detector, written negative.

It fires on the current token only. Its activation is near 0 on most words, and strongly
negative on words naming birds and insects. The size depends on how bird-like or
insect-like the word is:
  - birds, insects, poultry and their translations: about -1.2
  - chickens, livestock, cattle, wildlife, mammals, rodents, bees, mosquitoes, meteors: about -0.5
  - other small creatures, feathers, pests, predators, crops, weather words: about -0.2
The strong words are generic category nouns (bird, insect, poultry, livestock, wildlife);
specific species (owl, robin, pigeon, dog, cat, horse) are weak or about 0.
Ordinary words are about 0.

The program predicts the activation from the word alone (it ignores context), so the
conceptual part is the word groups; a lookup table of every token would explain more
variance but has no concept behind it.
"""

READS = ()

BIRDS_INSECTS = {
    "bird", "birds", "insect", "insects", "poultry", "禽", "鸟", "鳥", "小鸟", "昆虫", "🐦",
}
BIG_ANIMALS_FARM = {
    "chicken", "chickens", "livestock", "cattle", "wildlife", "mammal", "mammals",
    "rodent", "rodents", "meteor", "野生动物", "鸡", "畜", "bee", "bees", "蜂", "蜜蜂",
    "mosquito", "mosquitoes",
}
SMALL_CREATURES_ETC = {
    "bug", "bugs", "butterfly", "butterflies", "duck", "ducks", "goose", "geese", "feather",
    "feathers", "羽毛", "flock", "snake", "lizard", "animal", "animals", "creature",
    "creatures", "fish", "pest", "pests", "predator", "predators", "crop", "crops", "weather",
    "chicks", "wings", "flying", "蚊", "虫", "蝇", "蟲",
}


def activation_of_word(word: str) -> float:
    """Predicted activation for a token, from its word (lowercase, spaces removed)."""
    if word in BIRDS_INSECTS:
        return -1.2
    if word in BIG_ANIMALS_FARM:
        return -0.5
    if word in SMALL_CREATURES_ETC:
        return -0.2
    return 0.0


def step(carry, prefix, upstream):
    """One position: the current token's word decides the prediction; no state is carried."""
    word = prefix.token_strings[-1].strip().lower()
    return carry, float(activation_of_word(word))


if __name__ == "__main__":
    for word in ["bird", "insects", "chicken", "bee", "bug", "weather", "dog", "table"]:
        print(f"{word:10s} {activation_of_word(word):+.2f}")

programs.sol:
"""Sparse web-code and lexical-marker approximation.

Commerce declarations, Java web namespaces, and abbreviated web/type names
receive negative values. Expanded metadata names receive positive values.
A short document-local buffer separates code uses of list/map/new from prose.
Thinking/tool markup, Japanese possessive 'no', English suffix pieces, and
C include/logging markers have their own biases. Other tokens stay near zero;
most smaller word-specific activation variation is deliberately unmodeled.
"""
import re

READS = ()
WEB_ABBREVIATIONS = {'Http', 'Html', 'Json', 'Js', 'Api'}
TYPE_ABBREVIATIONS = {'Id', 'Param', 'Config', 'Attr'}
METADATA = {
    'configuration', 'metadata', 'parameter', 'parameters', 'attribute',
    'attributes', 'identifier', 'document', 'details', 'information',
}
CODE = re.compile(r'[{}=;\t]|\b(?:const|import|package|public|private)\b')
NOUN = re.compile(r'\b(?:a|an|the|this|that|our|your|my|their|of|in|to|on)$', re.I)
DECLARATION = re.compile(r'\b(?:const|let|var)$')
PACKAGE = re.compile(r'\bpackage\s+[^;\n]*$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    text = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('.(/')
    low = word.lower()
    code = bool(CODE.search(text))
    prose_noun = bool(NOUN.search(text.rstrip()))
    value = -0.001
    if token == '<think>':
        value = -0.13
    elif token in {'</think>', '<tool_call>', '</tool_response>'}:
        value = -0.08
    elif word == 'JsonResult':
        value = -0.6
    elif word in {'weixin', 'shiro'} and token.startswith('.'):
        value = -0.7 if PACKAGE.search(text) else -0.3
    elif low == 'goods' and DECLARATION.search(text.rstrip()):
        value = -0.7
    elif low in {'goods', 'shop'} and code and not prose_noun:
        value = -0.15
    elif word == 'oods' and text.endswith('/g'):
        value = -0.18
    elif word in WEB_ABBREVIATIONS:
        value = -0.13
    elif low == 'html':
        value = -0.09
    elif word in TYPE_ABBREVIATIONS or word in {'api', 'param'}:
        value = -0.08
    elif low in METADATA:
        value = 0.11 if word.istitle() and not token.startswith(' ') else 0.038
    elif word == 'Service':
        value = -0.10 if code else -0.02
    elif word in {'getList', 'getMap'} and token.startswith('.'):
        value = -0.30
    elif low in {'list', 'map'}:
        value = 0.06 if prose_noun else (-0.06 if code else 0.04)
    elif word == 'new':
        value = 0.05 if code and not prose_noun else -0.045
    elif word == 'の':  # Japanese possessive/linking particle
        value = -0.07
    elif token in {'ing', 'ed', 'ly', 'ion'}:  # English suffix pieces
        value = 0.022
    elif token == '#include':
        value = 0.12
    elif token == '.log':
        value = 0.08
    return (doc, (text + token)[-160:]), float(value)

programs.haiku:
"""Candidate: a few concept word sets. Negative for web-API / data-model identifiers,
positive for DOM and Java library call names. Everything else predicts 0."""
READS: tuple[str, ...] = ()

WEB_API_TERMS = {"Json", "json", "api", "API", "param", "Param", "Id", "Shop", "Service", "Util", "Tools", "OrderBy", "Where"}
LIBRARY_CALLS = {".addEventListener", ".getElementById", ".toString", "#include", "Impl", "Integer", "Parameters", "eslint", ".springframework", "_eq"}
NEG_VALUE = -0.15
POS_VALUE = 0.12


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word in WEB_API_TERMS:
        return None, NEG_VALUE
    if prefix.token_strings[-1] in LIBRARY_CALLS or word in LIBRARY_CALLS:
        return None, POS_VALUE
    return None, 0.0

programs.sol:
"""Approximate a local provenance and arrival signal.

Receiving/learning/deriving FROM a source, or being inspired/provided BY one,
is negative. COME TO/INTO/WITH and ARRIVE AT/IN are positive. Range and
separation uses of FROM are weaker. A source verb can precede a short object
or adverb. Chinese provenance words have negative lexical responses too.
Unrecognized tokens get zero; the 80-character suffix resets each document.
"""
import re

READS = ()


def forms(roots):
    """Ordinary English verb forms (irregular forms are listed separately)."""
    result = set()
    for root in roots.split():
        stem = root[:-1] if root.endswith('e') else root
        if root in {'run', 'stem'}:
            stem += root[-1]
        third = root + ('es' if root.endswith(('o', 'ch', 'sh', 's')) else 's')
        past = root + 'd' if root.endswith('e') else stem + 'ed'
        past = {'go': 'went', 'run': 'ran'}.get(root, past)
        result.update((root, third, stem + 'ing', past))
    return result


COME = {'come', 'comes', 'came', 'coming'}
ACQUIRE = forms('obtain receive collect gather acquire inherit retrieve earn borrow')
ACQUIRE |= set('learn learns learned learnt fetch fetched gained gleaned sourced'.split())
ORIGIN = forms('derive extract originate generate import sample recruit stem')
ORIGIN -= {'sample', 'samples'}  # Here these are usually objects, not verbs.
ORIGIN |= set('arise arises arising arose inferred learning'.split())
EVIDENCE = set('data evidence insights feedback inspiration input contributions'.split())
CONTENT = set('information advice knowledge lessons comments samples sample answers '
              'responses support money funding funds income revenue contribution'.split())
RESULT = set('taken returned returning downloaded downloading read reading recovered '
             'heard known adapted drawn emerged result results resulting resulted '
             'produced formed determined calculated selected purchased images '
             'content material quote news help heat energy signals findings reviews '
             'message request'.split())
RANGE = set('different differ differs difference distance distances far range ranges '
            'ranging vary varies apart aside start starting separated'.split())
MOTION = forms('go move shift run switch extend') | {'went', 'ran', 'miles'}
ARRIVE = forms('arrive') | {'arrival'}
FROM_CLASSES = ((-4.2, COME), (-3.9, ACQUIRE), (-2.9, ORIGIN), (-3.3, EVIDENCE),
                (-2.5, CONTENT), (-1.8, RESULT), (0.2, RANGE), (0.45, MOTION))
PROVIDERS = set('provided supplied sponsored funded powered informed'.split())
CAUSES = set('supported induced influenced motivated approved suggested requested'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = carry[1] if carry is not None and carry[0] == doc else ''
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    match = re.search(r'([a-z]+)\s*$', tail.lower())
    prev = match[1] if match else ''
    value = 0.0
    if word == 'from':
        value = -0.65 if prev else -0.2
        for strength, vocabulary in FROM_CLASSES:
            if prev in vocabulary:
                value = strength
                break
        # "Received an award from" and "came mainly from".
        phrase = re.split(r'[.!?;:\n]', tail.lower())[-1]
        words = re.findall(r'[a-z]+', phrase)[-5:]
        for distance, earlier in enumerate(reversed(words[:-1]), 1):
            if earlier in COME or earlier in ACQUIRE:
                if distance == 1 and prev.endswith('ly'):
                    context = -3.9
                else:
                    context = -0.65 - 3.4 * 0.6 ** distance
                value = min(value, context)
                break
        if token.strip() == 'From':
            value = -0.12
        if token == token.lstrip() and not tail.endswith((' ', '\n', '\t')):
            value = -0.1
    elif word == 'by':
        if prev in {'inspired', 'contributed'}:
            value = -2.25
        elif prev in PROVIDERS:
            value = -1.3
        elif prev in CAUSES:
            value = -1.0
        elif prev in {'generated', 'returned', 'taught', 'reported'}:
            value = -0.7
        elif prev in {'produced', 'determined', 'given', 'required', 'caused'}:
            value = -0.35
    elif prev in COME:
        value = {'to': 2.65, 'into': 2.6, 'in': 0.8, 'on': 1.8, 'with': 1.17,
                 'up': 1.4, 'at': 1.4, 'together': 1.6, 'under': 1.5}.get(word, 0.0)
        if word == 'to':
            value = {'came': 3.05, 'coming': 2.1}.get(prev, 2.65)
    elif prev in ARRIVE:
        value = {'at': 1.4, 'in': 0.65, 'to': 1.3}.get(word, 0.0)
    elif word == 'to' and prev in {'get', 'gets', 'got', 'learn', 'learned'}:
        value = 0.75
    elif word in {'to', 'with'} and re.search(
            r'\b(come|came|comes|coming) (up|back|down|out|together)$', tail.lower()):
        value = 1.6 if word == 'with' else 1.4
    elif word == 'on' and (prev in CONTENT or prev in EVIDENCE):
        value = 0.55
    elif word in {'来自', '來自'}:
        value = -3.2
    elif word in {'来源', '來源', '来源于', '來源於', '来自于'}:
        value = -2.1
    elif word == 'sources':
        value = -0.4
    return (doc, (tail + token)[-80:]), float(value)

"""Detect 'up'/raising spellings and examples, enumeration, and choices.

'Up' is stronger in take/bring/give/put phrases and weaker in end/follow/show
phrases, tested through the preceding token. 'Example' is positive except
after 'for'. Capitalized or attached 'up' spellings are weaker. Unlisted
tokens have zero response. The widespread small lexical background is
deliberately not modeled.
"""

READS = ()

# Chinese raising/straightening forms; Japanese age ('raise') and its fragments.
RAISING_FORMS = {
    '举': 5.5, '舉': 5.5, '举起': 3.0, '一举': 3.8,
    '上げ': 1.2, 'あげ': 1.2, 'げ': 1.2,
    '起': 0.35, '起来': 0.50, '上': 0.23,
    '抬': 1.50, '擎': 1.30, '翘': 0.85, '挺': 0.80,
}
# Chinese 'give/list an example', example nouns, and 'for example' connectives.
# The last two entries are Russian 'example' and 'for example'.
EXAMPLE_FORMS = {
    '举例': 2.25, '列举': 1.7, '例': 0.55,
    '例子': 0.85, '为例': 0.85, '例如': 0.15, '例えば': 0.15,
    'пример': 0.55, 'Например': 0.40,
}


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    word = text.strip()
    previous = ''
    if len(prefix.token_ids) > 1:
        if prefix.document_ids[-2] == prefix.document_ids[-1]:
            previous = prefix.token_strings[-2].strip()
    prev = previous.lower()

    if word.lower() == 'up':
        if not text.startswith(' '):
            return None, 0.76 if word == 'Up' else 0.40
        if word != 'up':
            return None, 0.85 if word == 'Up' else 0.60
        if prev in {'take', 'takes', 'taking', 'took', 'taken',
                    'bring', 'brings', 'bringing', 'brought'}:
            return None, 1.90
        if prev in {'give', 'gives', 'giving', 'gave', 'given',
                    'put', 'puts', 'putting'}:
            return None, 1.65
        if prev in {'come', 'comes', 'coming', 'came',
                    'keep', 'keeps', 'keeping', 'kept',
                    'pick', 'picks', 'picking', 'picked'}:
            return None, 1.35
        if prev in {'end', 'ends', 'ending', 'ended',
                    'follow', 'follows', 'following', 'followed',
                    'show', 'shows', 'showing', 'showed', 'shown'}:
            return None, 0.56
        return None, 0.93
    if word.lower() in {'-up', '-ups'}:
        return None, 0.56

    core = word.lstrip('._/@-').lower()
    if core == 'example':
        if prev == 'for':
            return None, -0.10 if previous == 'For' else -0.035
        return None, 0.74 if text.startswith(' ') else 0.65
    if core in {'examples', 'exemplary'}:
        return None, 0.90 if core == 'examples' else 0.56
    if core in {'enum', 'enums', 'enumeration', 'enumerations'}:
        if core == 'enum':
            return None, 1.20 if 'Enum' in word else 0.95
        return None, 0.70
    if core in {'choice', 'choices', 'chooser'}:
        return None, 1.00 if core == 'choice' else 0.70
    if core in {'lift', 'lifts', 'lifted', 'lifting'}:
        return None, 1.20 if core == 'lift' else 1.08
    if core in {'choose', 'chooses', 'choosing', 'chose', 'chosen', 'pick'}:
        return None, 0.23
    if core in {'upward', 'upwards'}:
        return None, 0.25
    if core in {'forth', 'aside'}:
        return None, 0.45
    return None, RAISING_FORMS.get(word, EXAMPLE_FORMS.get(word, 0.0))

programs.haiku:
"""Layer-0 MLP feature for the particle 'up' in phrasal verbs, and words for 'lift' or
'example/choice'.

Main case: the word ' up' after a verb that takes an object (take up, bring up, give up,
pick up, set up, make up) gives about 1.8; ' up' after other verbs (end up, wake up,
speed up, follow up) gives about 0.9. Same-meaning words: lift/lifting/lifted and their
Chinese/Japanese counterparts (举, 上げ, 拿, 挑) about 1.0. The noun 'example' or
'choice'/'examples' gives about 0.9, except after 'for', where 'for example' is near 0.
The particles down, out and forth give small values (0.15, 0.1, 0.4); unspaced 'up'
(as in 'up' or '-up' inside a compound) gives 0.4. Everything else is 0."""
READS = ()

TRANSITIVE = {"take", "taking", "takes", "took", "bring", "brings", "brought", "bringing",
              "give", "gives", "gave", "giving", "put", "puts", "hold", "holds", "held",
              "keep", "keeps", "kept", "keeping", "pick", "picks", "picked", "picking",
              "set", "sets", "setting", "make", "makes", "made", "making", "lift", "lifting"}
LIFT = {"lift", "lifting", "lifted", "Lift", "举", "舉", "举起", "上げ", "あげ", "げ", "拿", "挑",
        "挺", "翘"}
CHOICE = {"example", "examples", "Example", "Examples", "choice", "choices", "Choice",
          "EXAMPLE", "enum", "Enum", "@example", "/examples", "EXAMPLE"}
PARTICLE = {"up", "Up", "UP", "-up", "上", "forth"}

def step(carry, prefix, upstream):
    s = prefix.token_strings
    t = prefix.position
    raw = s[t]
    w = raw.strip()
    prev = s[t - 1].strip().lower() if t > 0 else ""
    if w in PARTICLE:
        if not raw.startswith(" ") and w != "上":
            return carry, 0.4
        if prev in TRANSITIVE:
            return carry, 1.8
        return carry, 0.9
    if w in ("down", "out", "forth"):
        return carry, {"down": 0.15, "out": 0.1, "forth": 0.4}[w]
    if w in LIFT:
        return carry, 1.0
    if w in CHOICE:
        if prev == "for":
            return carry, 0.0
        return carry, 0.9
    return carry, 0.0

programs.luna:
"""Predict a sparse lexical cue: “up” and example-related words."""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word == "up":
        return None, 1.0
    if word in {"example", "examples", "exemplary"}:
        return None, 0.75
    return None, 0.0

"""Give a small estimate for software/runtime words and API identifiers.

The cues are sparse in the harvested examples, so this uses them as a weak
hint rather than treating every matching word as a strong activation.
"""

READS = ()

import re

RUNTIME_NAMES = frozenset({
    "object", "file", "system", "process", "event", "handle", "path",
    "string", "gui", "application", "registry", "extension", "service",
})
LANGUAGE_LITERALS = frozenset({"null", "nil", "true", "int", "void"})
METHOD_NAMES = frozenset({"get", "getint", "getmethod", "read", "find",
                          "resolve", "add", "destroy"})


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1].strip()
    word = text.lower()
    cue = 0.0

    if word in RUNTIME_NAMES:
        cue += 0.20
    if word in LANGUAGE_LITERALS:
        cue += 0.32
    if re.search(r"[a-z][A-Z]", text) or text.isupper() and len(text) > 1:
        cue += 0.35
    if text.startswith(".") and word[1:] in METHOD_NAMES:
        cue += 0.38

    return None, float(0.2 * min(cue, 0.75))

programs.sol:
"""Approximate separator pulses after markup, and responses at document resets.

Dollar signs, backticks, emphasis/underscore marks, Japanese closing quotes,
and diff-hunk markers can precede a negative pulse. Whitespace, punctuation,
and spaced words give different pulse sizes. A space before the marker is
used as an opening cue; attached letters/digits can instead be positive.
This is a local cue, not a parser tracking matched opening/closing spans.
Document-initial words and chat headers have separate negative responses;
nonbreaking spaces and chat/thought control markers have fixed baselines.
The program does not reconstruct the vocabulary-specific background activity.
"""
READS = ()


def boundary(marker, token):
    dollar = marker.endswith("$")
    double_dollar = marker.endswith("$$")
    code = marker.endswith("`")
    opening_cue = marker.startswith(" ")
    strength = 1.0 if dollar else 0.7 if code else 0.55
    if double_dollar:
        strength = 1.25
    if marker.endswith("_"):
        strength = 0.5
    if marker.endswith("」"):
        strength = 0.3
    stripped = token.lstrip()
    if token.isspace():
        if "\xa0" in token:
            value = -0.55 - 0.5 / len(token) ** 0.5
            if opening_cue:
                value += 0.3
            return value
        if "\n" in token:
            value = -0.6 if dollar else -0.69 if code else -0.34
            if double_dollar:
                value = -0.76
            if opening_cue and code:
                value = -0.23
            if marker.endswith("」"):
                value = -0.18
            return value
        return -0.9 * strength / len(token) ** 0.8
    if not stripped:
        return 0.0
    first = stripped[0]
    if token[0].isspace():
        if first.isalpha():
            return -0.29 * strength
        if first in "$`*_":
            return 0.02
        return -0.7 * strength
    if first.isdigit():
        return 0.09 if (dollar or code) else 0.03
    if first.isalpha():
        return 0.09 if opening_cue or double_dollar else 0.02
    if first in ",.;:!?":
        value = -0.8 if first == "," else -0.47
        return value * strength
    if first == "\\":
        return -0.36 if double_dollar else -0.55 if dollar else -0.18
    if first in ")]}":
        return -0.35 * strength
    if code and opening_cue:
        return 0.09
    if first in "$`*_":
        return 0.02
    return -0.08 * strength


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        position, previous = 0, ""
    else:
        _, position, previous = carry
    value = 0.0
    if token.isspace() and "\xa0" in token:
        value = -0.11
    if token == "<think>":
        value = 0.20
    elif token == "<|im_end|>":
        value = 0.073
    elif token == "</tool_call>":
        value = 0.068
    if position == 0 and token == "<|im_start|>":
        value = -0.796
    elif position == 0 and token.strip()[:1].isalpha():
        value = -0.05
    elif position == 1 and previous == "<|im_start|>":
        value = {"user": -0.313, "assistant": -0.485,
                 "system": -0.582}.get(token, 0.0)
    elif previous.endswith(("$", "`", "**", "_", "」", "@@")):
        value = boundary(previous, token)
    return (doc, position + 1, token), float(value)

programs.haiku:
"""Layer-0 MLP down-projection component 1021: a sparse, mostly-silent feature.

Its activation is ~0 on almost every token. It goes clearly negative on a few
concrete things and mildly positive on a couple of others:

- a chat/document boundary: the <|im_start|> token that begins a new packed
  document right after <|endoftext|> (always about -0.8), and the role word
  "user" right after that <|im_start|> (about -0.1);
- non-breaking spaces (U+00A0), which show up as indentation in code pasted
  from the web (about -0.15 to -0.35);
- a newline pair right after a closing "$" of display maths (about -0.75);
- the reasoning tag <think> (about +0.2) and the end-of-turn tag <|im_end|> (about +0.07).

Everything else predicts 0. The rules capture only the large, recognisable events;
the bulk of the variance is small, context-dependent noise they do not explain.
"""

READS = ()

NBSP = " "


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    cur = toks[-1]
    prev = toks[-2] if len(toks) > 1 else ""
    if cur == "<|im_start|>" and prev == "<|endoftext|>":
        return None, -0.8
    if cur == "user" and prev == "<|im_start|>":
        return None, -0.1
    if cur == "\n\n" and prev.endswith("$"):
        return None, -0.75
    if NBSP in cur:
        return None, -0.2
    if cur == "<think>":
        return None, 0.2
    if cur == "<|im_end|>":
        return None, 0.07
    return None, 0.0

programs.luna:
"""Use a cautious small correction at chat-message starts."""
READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    previous, previous_doc = carry if carry is not None else (None, None)
    doc = prefix.document_ids[-1]

    value = 0.0
    if token == "<|im_start|>":
        value = -0.04
    elif previous == "<|im_start|>" and previous_doc == doc:
        if token == "user":
            value = -0.016
        elif token == "assistant":
            value = -0.024
        elif token == "system":
            value = -0.029

    return (token, doc), value

"""Spot a closing mark at a syntax or quotation boundary.

The sampled high-response examples mostly close a parenthesis, bracket, or
brace, often as a line ends. These cues are noisy, so the program predicts a
moderate negative pulse rather than treating every such token as a full response.
"""

READS = ()

def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    end = token.rstrip()
    if token.endswith("\n") and end.endswith((")", "]", "}")):
        return None, -0.5
    if end.endswith((")", "]", "}")):
        return None, -0.275
    if token.endswith("\n"):
        previous = prefix.token_strings[-2] if len(prefix) > 1 else ""
        if previous.strip().endswith(("else", "try", "finally")):
            return None, -0.4
    return None, 0.0

programs.sol:
"""Lexical distributive-quantifier signal: each, every, per, and translations.

Chinese 每 (each/every) has the strongest negative response. Its compounds,
other languages' distributive words, repeated-time words, and each-loop names
get smaller negative estimates. Any/both get weak positive estimates. Spelling,
case, and leading space distinguish word tokens from code or word fragments.
UTF-8 fragments of 每/毎/各 are handled explicitly. Unlisted tokens get zero;
no noun, quantifier scope, or later context is inferred.
"""
READS = ()

# This vocabulary token is the shared UTF-8 lead bytes E6 AF of 每 and 毎.
# Its response is estimated before the remaining byte reveals the character.
EACH_IDEOGRAPH_UTF8_LEAD = 29975
# Translations of each/every, including frequent inflections and tokenized stems.
EACH_WORDS = {
    'cada': -1.9,       # Spanish / Portuguese
    'chaque': -1.3,     # French
    'chac': -1.2,       # stem of chacun/chacune
    'ogni': -0.8,       # Italian
    'jeder': -0.5,      # German
    'jedem': -0.85,
    'jede': -0.4,
    'кажд': -2.56,      # Russian
    'ажд': -1.4,
    'каждый': -1.84,
    'каждого': -1.93,
    'каждой': -1.6,
    'каждом': -2.34,
    'каж': -0.41,
    'кож': -0.82,       # Ukrainian stem
    'każdy': -1.0,      # Polish
    'każdego': -1.1,
    'mỗi': -2.05,       # Vietnamese
    'iap': -1.2,        # Indonesian tiap, tokenized after t
    'لكل': -1.2,        # Arabic: for each
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    s = raw.strip()
    w = s.lower()
    spaced = raw[:1].isspace()
    capital = s[:1].isupper()
    value = 0.0
    if w == 'each':
        value = (-1.9 if capital else -1.82) if spaced else (
            -1.95 if capital else -1.6)
    elif w == 'every':
        value = -0.94
        if capital and spaced:
            value = -0.68 if s.isupper() else -1.17
    elif w == 'per':
        value = -0.72 if capital else (-1.03 if spaced else -0.50)
    elif w in ('.each', '_each'):
        value = -2.4 if w[0] == '.' else -1.76
    elif w.lstrip('._') == 'foreach':
        value = -0.97
        if 'E' in s:
            value = -1.35 if raw[:1] in '. ' else -1.15
    elif w in ('beforeeach', 'aftereach'):
        value = -0.8 if w.startswith('before') else -1.04
    elif w in ('-per', '_per', '.per'):
        value = -0.85
    elif w in EACH_WORDS:
        value = EACH_WORDS[w]
    elif s == 'كل':
        value = -1.25 if spaced else -0.3
    elif s == '每':
        value = -7.0
    elif s == '每一':
        value = -4.3
    elif s in ('每个', '每個', '每每'):
        value = -3.0
    elif s.startswith('每'):
        if s.endswith('都'):
            value = -0.95
        else:
            value = -2.3 if len(s) <= 2 else -1.9
    elif s == '各':
        value = -1.1
    elif s.startswith('各'):
        value = -0.55
    elif s == '각':
        value = -1.24 if spaced else -0.65
    elif s == '日々':
        value = -0.84
    elif s in ('逐', '日常', 'それぞれ'):
        value = -0.60
    elif w in ('daily', 'annually', 'nightly', 'täglich'):
        value = -0.46
    elif w == 'annual':
        value = -0.27
    elif w == 'any':
        value = 0.10
    elif w == 'both':
        value = 0.07
    elif w == 'everyone':
        value = -0.25 if capital else -0.14
    elif s == '所有':
        value = -0.38
    elif prefix.token_ids[-1] == EACH_IDEOGRAPH_UTF8_LEAD:
        value = -1.89
    # A UTF-8 fragment can complete a quantifier that is not visible alone.
    same_document = len(prefix.document_ids) > 1 and (
        prefix.document_ids[-2] == prefix.document_ids[-1])
    if '\ufffd' in s and same_document:
        end = prefix.text_prefixes[-1][-1:]
        if end == '每':
            value = -6.64
        elif end == '毎':
            value = -4.34
        elif end == '各':
            value = -1.29
    return None, value

programs.haiku:
"""Distributive-quantifier detector (layer 0 MLP down_proj, component 1023).

This component is silent almost everywhere. It switches on (strongly negative)
on the word that introduces "one for each / every / per one" meaning:
  * English "each" (most of all: " each", " Each", "each", ".each", "forEach")
  * English "every" and "per" (weaker: about half as strong as "each")
  * the Chinese 每 ("every/each"), strongest on the bare character, weaker on
    compounds such as 每年, 每天, 每个
  * "each" in other languages: cada, chaque, ogni, jeder, каждый, كل, ...

Predicted activation = a per-word strength for the current token. Everything
else is 0. The current token is all it needs, so there is no carried state.
"""

import re

READS = ()

EACH = -1.8          # English "each" family
EVERY_PER = -1.0     # "every", "per"
CHINESE_BARE = -7.0  # the bare character 每
CHINESE_COMPOUND = -2.5  # 每年, 每天, 每个 ...
OTHER_EACH = -1.5    # each in other languages

OTHER_EACH_WORDS = {
    "cada", "chaque", "ogni", "jeder", "jede", "jedem",
    "каждый", "каждого", "каждой", "кажд", "każdy", "كل",
}


def _word(text):
    """Lower-case letters only: ' Each' -> 'each', '.forEach' -> 'foreach'."""
    return re.sub(r"[^a-z]", "", text.lower())


def _strength(text):
    word = _word(text)
    if word in ("each", "foreach", "beforeeach"):
        return EACH
    if word in ("every", "per"):
        return EVERY_PER
    if text.strip() == "每":
        return CHINESE_BARE
    if "每" in text:
        return CHINESE_COMPOUND
    if word in OTHER_EACH_WORDS:
        return OTHER_EACH
    return 0.0


def step(carry, prefix, upstream):
    return None, float(_strength(prefix.token_strings[-1]))
